/* Views C: Finance, Communications, Documents, Integrations, Analytics, Notifications, Administration */
(function(){

/* ===================== FINANCE ===================== */
function periods(){
  const y = +TODAY.slice(0,4), m = +TODAY.slice(5,7); const mm = (Y,M)=>Y+'-'+String(M).padStart(2,'0');
  const qStart = Math.floor((m-1)/3)*3+1; const last = (Y,M)=>iso(new Date(Date.UTC(Y,M,0)));
  const p12 = calc.monthly(12).map(x=>x.m);
  return {
    month:{l:'This month', from:mm(y,m)+'-01', to:last(y,m), months:[mm(y,m)]},
    quarter:{l:'This quarter', from:mm(y,qStart)+'-01', to:last(y,qStart+2), months:[0,1,2].map(i=>mm(y,qStart+i))},
    year:{l:String(y), from:y+'-01-01', to:y+'-12-31', months:Array.from({length:12},(_,i)=>mm(y,i+1))},
    all:{l:'Last 12 months', from:p12[0]+'-01', to:last(y,m), months:p12}
  };
}
function ledger(){
  const inc = DB.invoices.flatMap(i=>i.payments.map(p=>({date:p.date, type:'Income', desc:`${i.id} · ${i.desc}`, clientId:i.clientId, projectId:i.projectId, cat:p.method, ref:p.ref, amount:p.amount, exvat:p.amount/(1+i.vat), go:'invoices-'+i.id})));
  const exp = DB.expenses.map(x=>({date:x.date, type:'Expense', desc:x.vendor+(x.note?' · '+x.note:''), clientId:x.projectId&&get.project(x.projectId)?get.project(x.projectId).clientId:null, projectId:x.projectId, cat:x.category, ref:x.id, amount:-x.amount, exvat:-x.amount, act:`data-a="editExpense" data-id="${x.id}"`}));
  return inc.concat(exp).sort((a,b)=>b.date.localeCompare(a.date));
}
const projCost = p => (p.cost||0) + sum(DB.expenses.filter(x=>x.projectId===p.id), x=>x.amount);
window.projCost = projCost;
Views.finance = () => {
  const per = uv('finP','year'); const PS = periods(); const P = PS[per] || PS.year; const fc = UI.f.finC||'', fp = UI.f.finPr||'';
  const inP = d => d && d>=P.from && d<=P.to;
  const invs = DB.invoices.filter(i=>(!fc||i.clientId===fc) && (!fp||i.projectId===fp));
  const revenue = sum(invs.flatMap(i=>i.payments.filter(p=>inP(p.date)).map(p=>p.amount/(1+i.vat))));
  const outstanding = sum(invs, i=>calc.inv(i).outstanding);
  const qs = DB.quotes.filter(q=>(!fc||q.clientId===fc) && (!fp||q.projectId===fp));
  const accepted = sum(qs.filter(q=>q.status==='Accepted' && inP(q.accepted)), q=>calc.quote(q).sub);
  const quoted = sum(qs.filter(q=>q.status!=='Draft' && inP(q.sent||q.created)), q=>calc.quote(q).sub);
  const exps = DB.expenses.filter(x=>inP(x.date) && (!fp||x.projectId===fp) && (!fc||(x.projectId&&get.project(x.projectId)&&get.project(x.projectId).clientId===fc)));
  const costs = sum(exps, x=>x.amount);
  const projs = DB.projects.filter(p=>(!fc||p.clientId===fc) && (!fp||p.id===fp));
  const active = projs.filter(p=>!['Completed','On hold'].includes(p.status));
  const estProfit = sum(active, p=>{ const pc=projCost(p), pr=calc.progress(p); return p.budget - (pr>=15 ? Math.min(pc/(pr/100), p.budget*1.5) : pc); });
  const mrr = fc ? sum(DB.retainers.filter(r=>r.clientId===fc && (!r.until||r.until>=TODAY)),r=>r.monthly) : calc.mrr();
  const kp = [
    {l:'Revenue received', v:fmtRk(revenue), d:'Ex VAT · '+P.l, tone:'up', icon:'banknote'},
    {l:'Outstanding invoices', v:fmtR(outstanding), d:`${invs.filter(i=>calc.inv(i).overdue).length} overdue`, tone:outstanding?'down':'', icon:'hourglass', go:'invoices'},
    {l:'Accepted quote value', v:fmtRk(accepted), d:'Accepted in period', icon:'badge-check'},
    {l:'Total quoted value', v:fmtRk(quoted), d:'Sent in period', icon:'file-text'},
    {l:'Monthly recurring', v:fmtR(mrr), d:`${DB.retainers.filter(r=>!r.until||r.until>=TODAY).length} active retainers`, icon:'repeat'},
    {l:'Expenses', v:fmtRk(costs), d:`${exps.length} recorded in period`, icon:'receipt'},
    {l:'Estimated profit', v:fmtRk(estProfit), d:'Active projects, forecast', icon:'trending-up'},
    {l:'Actual profit', v:fmtRk(revenue-costs), d:revenue?pct(revenue-costs, revenue)+'% margin':'Revenue less expenses', tone:revenue-costs>=0?'up':'down', icon:'wallet'}
  ];
  const series = calc.monthly(12);
  const svc = {}; DB.invoices.forEach(i=>{ const p = i.projectId && get.project(i.projectId); const k = p ? p.category : 'Retainers & other'; const v = sum(i.payments,x=>x.amount)/(1+i.vat); if(v) svc[k] = (svc[k]||0) + v; });
  const svcItems = Object.entries(svc).map(([k,v])=>({label:k, value:v, color:CAT_COLOR[k]||'var(--c5)'})).sort((a,b)=>b.value-a.value);
  const byClient = DB.clients.map(c=>({c, rec:sum(DB.invoices.filter(i=>i.clientId===c.id),i=>calc.inv(i).received), out:calc.outstanding(c)})).filter(x=>x.rec+x.out>0).sort((a,b)=>(b.rec+b.out)-(a.rec+a.out)).slice(0,8);
  const profit = DB.projects.filter(p=>p.budget>0 && (projCost(p)>0||p.status==='Completed')).map(p=>{ const pc=projCost(p), pr=calc.progress(p); const fcst = p.status==='Completed'||pr<15?pc:Math.min(pc/(pr/100), p.budget*1.5); return {p, m:Math.round((p.budget-fcst)/p.budget*100)}; }).sort((a,b)=>b.m-a.m);
  const led = ledger().filter(t=>inP(t.date) && (!fc||t.clientId===fc) && (!fp||t.projectId===fp));
  const noData = (m,i) => empty(i||'bar-chart-3','No data yet',m);
  const html = `<div class="page full">${pageHead('Finance', 'Revenue, receivables, expenses and profitability. All amounts in South African Rand.', `<button class="btn" data-a="newRetainer">${ic('repeat',14)}Add retainer</button><button class="btn" data-a="newExpense">${ic('minus-circle',14)}Record expense</button><button class="btn" data-go="invoices">${ic('receipt',14)}Invoices</button>`)}
    <div class="toolbar">${segc('finP',[['month','Month'],['quarter','Quarter'],['year','Year'],['all','12 months']],per)}<select class="sel sm" data-ch="filt" data-key="finC" aria-label="Client">${clientOpts(fc,'All clients')}</select><select class="sel sm" data-ch="filt" data-key="finPr" aria-label="Project">${opts(DB.projects.map(p=>[p.id,p.name]), fp, {blank:'All projects'})}</select>${(fc||fp)?`<button class="btn ghost sm" data-a="clearFin">${ic('x',13)}Clear</button>`:''}</div>
    <div class="kpis" style="grid-template-columns:repeat(4,minmax(0,1fr));margin-bottom:16px">${kp.map(kpiCell).join('')}</div>
    <div class="grid g-21">
      ${card('Revenue vs expenses', series.some(m=>m.revenue||m.costs)?`<div class="legend" style="margin-bottom:8px"><span><i style="background:var(--c1)"></i>Revenue</span><span><i style="background:var(--c5)"></i>Expenses</span></div>${chBars({labels:series.map(m=>fmtM(m.m).slice(0,3)), series:[{name:'Revenue',values:series.map(m=>m.revenue),color:'var(--c1)'},{name:'Expenses',values:series.map(m=>m.costs),color:'var(--c5)'}], h:230})}`:noData('Record payments and expenses to build this chart.','banknote'), {hint:'Last 12 months · ex VAT'})}
      ${card('Revenue by project type', svcItems.length?chDonut({items:svcItems, center:{v:fmtRk(sum(svcItems,x=>x.value)), l:'collected'}}):noData('Paid invoices grouped by project category.','pie-chart'), {hint:'Paid invoices'})}
    </div>
    <div class="grid g3 mt-16">
      ${card('Received vs outstanding', byClient.length?`${chHBar({items:byClient.map(x=>({label:x.c.name, value:x.rec+x.out, color:'var(--c3)', valueHtml:fmtRk(x.rec+x.out), tip:`${x.c.name}\nReceived ${fmtR(x.rec,true)}\nOutstanding ${fmtR(x.out,true)}`, go:'client-'+x.c.id, labelHtml:esc(x.c.name.split(' ').slice(0,2).join(' ')), marker:x.rec}))})}<p class="muted xs mt-8">Bar = total invoiced incl. VAT · marker = amount received</p>`:noData('Invoiced and received amounts per client.','users'))}
      ${card('Project profitability', profit.length?chHBar({items:profit.map(x=>({label:x.p.name, value:Math.max(0,x.m), color:x.m<15?'var(--red)':x.m<30?'var(--amber)':'var(--green)', valueHtml:x.m+'%', tip:`${x.p.name}\nBudget ${fmtR(x.p.budget)} · cost to date ${fmtR(projCost(x.p))}\nForecast margin ${x.m}%`, go:'project-'+x.p.id})), max:100, fmt:v=>v+'%'}):noData('Add project costs (in the project or as expenses linked to a project).','trending-up'), {hint:'Forecast margin'})}
      ${card('Monthly cash collection', series.some(m=>m.collected)?chArea({labels:series.map(m=>fmtM(m.m).slice(0,3)), series:[{name:'Collected',values:series.map(m=>m.collected),color:'var(--c3)'}], h:230, w:480}):noData('Payments received per month (incl. VAT).','banknote'), {hint:'Incl. VAT'})}
    </div>
    <div class="grid g2 mt-16">
      ${card('Retainers', DB.retainers.length?table({key:'ret', rows:DB.retainers, act:r=>`data-a="editRetainer" data-id="${r.id}"`, cols:[{k:'clientId',l:'Client',r:r=>esc((get.client(r.clientId)||{name:'—'}).name)},{k:'name',l:'Service'},{k:'since',l:'Since',r:r=>fmtD(r.since)},{k:'until',l:'Status',r:r=>r.until&&r.until<TODAY?badge('Ended','gray'):badge('Active','green')},{k:'monthly',l:'Monthly (ex VAT)',cls:'r',r:r=>`<span class="num">${fmtR(r.monthly)}</span>`}]}):empty('repeat','No retainers','Add monthly support or partnership agreements to track recurring revenue.',`<button class="btn sm" data-a="newRetainer">${ic('plus',13)}Add retainer</button>`), {flush:true})}
      ${card('Expense categories · '+esc(P.l), exps.length?chHBar({items:uniq(exps.map(x=>x.category)).map(k=>({label:k, value:sum(exps.filter(x=>x.category===k),x=>x.amount), color:'var(--c5)'})).sort((a,b)=>b.value-a.value)}):empty('receipt','No expenses in this period','',`<button class="btn sm" data-a="newExpense">${ic('plus',13)}Record expense</button>`))}
    </div>
    <div class="section-t">Transactions · ${esc(P.l)}</div>
    ${card(null, table({key:'ledger', rows:led, go:t=>t.go||'', act:t=>t.act||'', cols:[
      {k:'date',l:'Date',r:t=>fmtD(t.date)},{k:'type',l:'Type',r:t=>badge(t.type, t.type==='Income'?'green':'gray')},{k:'desc',l:'Description',r:t=>`<span class="cell-t">${esc(t.desc)}</span>`},{k:'clientId',l:'Client',r:t=>t.clientId&&get.client(t.clientId)?esc(get.client(t.clientId).name):'<span class="muted">Overheads</span>',sv:t=>t.clientId||''},{k:'projectId',l:'Project',r:t=>t.projectId?`<span class="mono small">${t.projectId}</span>`:'<span class="muted">—</span>'},{k:'cat',l:'Method / category'},{k:'ref',l:'Reference',r:t=>`<span class="mono small">${esc(t.ref)}</span>`},{k:'amount',l:'Amount',cls:'r',r:t=>`<span class="num ${t.amount>0?'up':''}">${t.amount>0?'+':'−'}${fmtR(Math.abs(t.amount),true)}</span>`}
    ], foot:led.length?`<td colspan="7">${led.length} transactions</td><td class="r num">${fmtR(sum(led,t=>t.amount),true)}</td>`:'', emptyMsg:empty('receipt','No transactions in this period','Payments recorded on invoices and expenses you record appear here.')}), {flush:true})}
  </div>`;
  return {html, crumbs:[['Finance']], title:'Finance'};
};
A.clearFin = () => { UI.f.finC=''; UI.f.finPr=''; rerender(); };
const EXP_CATS = ['Contractor','Software','Infrastructure','AI usage','Hardware','Office','Travel','Marketing','Professional fees','Salaries','Bank charges','Other'];
function expenseForm(x){ return `<div class="form-grid">${field('Supplier / description *',`<input class="inp" id="ex-vendor" value="${esc(x.vendor||'')}" placeholder="e.g. n8n Cloud subscription">`,'span2')}${field('Amount (R) *',`<input class="inp num" type="number" step="0.01" id="ex-amt" value="${x.amount||''}">`)}${field('Date',`<input class="inp" type="date" id="ex-date" value="${x.date||TODAY}">`)}${field('Category',`<select class="sel" id="ex-cat">${opts(EXP_CATS, x.category||'Software')}</select>`)}${field('Project (optional)',`<select class="sel" id="ex-proj">${opts(DB.projects.map(p=>[p.id,p.id+' · '+p.name]), x.projectId||'', {blank:'Overheads — no project'})}</select>`)}${field('Note',`<input class="inp" id="ex-note" value="${esc(x.note||'')}">`,'span2')}</div><p class="muted xs mt-12">Enter amounts as paid. Expenses linked to a project count towards its cost and profitability.</p>`; }
A.newExpense = () => { closePop(); modal({title:'Record expense', body:expenseForm({}), foot:`<button class="btn ghost" data-a="closeTop">Cancel</button><button class="btn pri" data-a="saveExpense">${ic('check',14)}Save expense</button>`}); };
A.editExpense = d => { const x=DB.expenses.find(e=>e.id===d.id); modal({title:'Edit expense '+x.id, body:expenseForm(x), foot:`<button class="btn danger" data-a="delExpense" data-id="${x.id}" style="margin-right:auto">${ic('trash-2',14)}Delete</button><button class="btn ghost" data-a="closeTop">Cancel</button><button class="btn pri" data-a="saveExpense" data-id="${x.id}">Save</button>`}); };
A.saveExpense = d => { if(!requireFields([['ex-vendor','Description'],['ex-amt','Amount']])) return; const amt=+val('ex-amt'); if(!(amt>0)) return toast('Amount must be greater than zero','err'); let x = d.id ? DB.expenses.find(e=>e.id===d.id) : {id:nextId('X-',DB.expenses)}; Object.assign(x,{vendor:val('ex-vendor'), amount:Math.round(amt*100)/100, date:val('ex-date')||TODAY, category:val('ex-cat'), projectId:val('ex-proj')||null, note:val('ex-note')}); if(!d.id) DB.expenses.push(x); log(`${d.id?'Updated':'Recorded'} expense ${esc(x.vendor)} ${fmtR(x.amount,true)}`, null, 'finance', 'invoice'); closeTop(); commit(d.id?'Expense updated':'Expense recorded'); };
A.delExpense = d => { closeTop(); confirmBox({title:'Delete expense?', text:'This permanently removes the expense record.', ok:'Delete', danger:true, onOk:()=>{ DB.expenses = DB.expenses.filter(e=>e.id!==d.id); commit('Expense deleted'); }}); };
function retainerForm(r){ return `<div class="form-grid">${field('Client *',`<select class="sel" id="rt-client">${clientOpts(r.clientId||'','Select client')}</select>`)}${field('Service *',`<input class="inp" id="rt-name" value="${esc(r.name||'')}" placeholder="e.g. Hosting & support">`)}${field('Monthly amount ex VAT (R) *',`<input class="inp num" type="number" id="rt-amt" value="${r.monthly||''}">`)}${field('Start date',`<input class="inp" type="date" id="rt-since" value="${r.since||TODAY}">`)}${field('End date (optional)',`<input class="inp" type="date" id="rt-until" value="${r.until||''}">`)}</div>`; }
A.newRetainer = () => modal({title:'Add retainer', body:retainerForm({}), foot:`<button class="btn ghost" data-a="closeTop">Cancel</button><button class="btn pri" data-a="saveRetainer">Save retainer</button>`});
A.editRetainer = d => { const r=DB.retainers.find(x=>x.id===d.id); modal({title:'Edit retainer', body:retainerForm(r), foot:`<button class="btn danger" data-a="delRetainer" data-id="${r.id}" style="margin-right:auto">${ic('trash-2',14)}Delete</button><button class="btn ghost" data-a="closeTop">Cancel</button><button class="btn pri" data-a="saveRetainer" data-id="${r.id}">Save</button>`}); };
A.saveRetainer = d => { if(!requireFields([['rt-client','Client'],['rt-name','Service'],['rt-amt','Monthly amount']])) return; let r = d.id ? DB.retainers.find(x=>x.id===d.id) : {id:nextId('R-',DB.retainers)}; Object.assign(r,{clientId:val('rt-client'), name:val('rt-name'), monthly:+val('rt-amt')||0, since:val('rt-since')||TODAY, until:val('rt-until')||null}); if(!d.id) DB.retainers.push(r); log(`${d.id?'Updated':'Added'} retainer <b>${esc(r.name)}</b> ${fmtR(r.monthly)}/month`, r.clientId, 'finance', 'invoice'); closeTop(); commit('Retainer saved'); };
A.delRetainer = d => { closeTop(); confirmBox({title:'Delete retainer?', text:'Use an end date instead if the retainer has simply ended — that keeps your recurring revenue history.', ok:'Delete', danger:true, onOk:()=>{ DB.retainers = DB.retainers.filter(x=>x.id!==d.id); commit('Retainer deleted'); }}); };

/* ===================== COMMUNICATIONS ===================== */
const CTABS = [['all','All','inbox'],['email','Email','mail'],['whatsapp','WhatsApp','message-circle'],['call','Calls','phone'],['meeting','Meetings','video'],['note','Internal notes','sticky-note']];
function threadHtml(cv, inline){
  const c = get.client(cv.clientId); const p = cv.projectId && get.project(cv.projectId);
  const msgs = cv.channel==='whatsapp'
    ? `<div class="bubble-wrap">${cv.messages.map(m=>{ const mine = DB.users.some(u=>u.name===m.from); return `<div class="bubble ${mine?'me':''}">${esc(m.body)}<div class="bm">${esc(m.from)} · ${fmtDT(m.at)}${m.sim?' · logged':''}</div></div>`; }).join('')}</div>`
    : `<div class="col gap-12">${cv.messages.map(m=>`<div class="card"><div class="card-b"><div class="row between" style="margin-bottom:8px"><div class="row"><span class="av sm" style="background:var(--surface-3);color:var(--fg-2)">${initials(m.from)}</span><b class="small">${esc(m.from)}</b>${m.sim?'<span class="tag">Logged</span>':''}</div><span class="muted xs">${fmtDT(m.at)}</span></div><div style="white-space:pre-line;line-height:1.6;color:var(--fg-2)">${esc(m.body)}</div>${m.attachments&&m.attachments.length?`<div class="row wrap mt-12">${m.attachments.map(a=>`<span class="tag">${ic('paperclip',12)}${esc(a)}</span>`).join('')}</div>`:''}</div></div>`).join('')}</div>`;
  return `<div class="col gap-16"><div class="row between wrap" style="align-items:flex-start"><div><div class="row">${srcIcon(cv.channel)}<h2 style="font-size:16px">${esc(cv.subject)}</h2></div><div class="muted small mt-8">${CH_LABEL[cv.channel]} · <a href="#client-${c.id}">${esc(c.name)}</a>${p?` · <a href="#project-${p.id}">${esc(p.name)}</a>`:''} · ${esc(cv.participants.join(', '))}</div></div><div class="row"><label class="muted small" for="fu-${cv.id}">Follow-up</label><select class="sel sm" id="fu-${cv.id}" data-ch="convFollow" data-id="${cv.id}">${opts(['Open','Awaiting client','Scheduled','Overdue','Done'], cv.followUp)}</select></div></div>
    <div class="kv2" style="grid-template-columns:repeat(3,1fr)"><div><div class="k">Assigned</div><div class="v">${who(cv.assigned)}</div></div><div><div class="k">Client contact</div><div class="v">${esc(c.contact)}</div></div><div><div class="k">Recipient</div><div class="v small mono">${esc(cv.channel==='whatsapp'?c.whatsapp:c.email)}</div></div></div>
    ${msgs}
    ${['email','whatsapp'].includes(cv.channel)?`<div class="card"><div class="card-b"><textarea class="ta" id="rp-${cv.id}" placeholder="Write a reply…"></textarea><div class="row between mt-8"><span class="muted xs">${ic('flask-conical',12)} Saved to the history only — send it from your mail or WhatsApp app.</span><div class="row"><button class="btn pri sm" data-a="sendReply" data-id="${cv.id}">${ic('check',13)}Save reply</button></div></div></div></div>`:`<button class="btn sm" data-a="logActivity" data-client="${c.id}" style="align-self:flex-start">${ic('plus',13)}Log another ${cv.channel==='note'?'note':cv.channel}</button>`}
  </div>`;
}
Views.comms = () => {
  const tab = uv('ctabc','all'); const q=(UI.q.comms||'').toLowerCase();
  const rows = DB.conversations.filter(c=>(tab==='all'||c.channel===tab) && (!q || [c.subject, get.client(c.clientId).name, c.messages.map(m=>m.body).join(' ')].join(' ').toLowerCase().includes(q))).sort((a,b)=>b.messages[b.messages.length-1].at.localeCompare(a.messages[a.messages.length-1].at));
  let sel = get.conv(UI.v.convSel); if(!sel || !rows.includes(sel)) sel = rows[0];
  const html = `<div class="page full">${pageHead('Communications', 'Every email, WhatsApp, call, meeting and note — linked to a client and project.', `<button class="btn pri" data-a="compose">${ic('send',14)}Compose</button>`)}
    ${tabsc('ctabc', CTABS.map(([v,l])=>[v,l, v==='all'?DB.conversations.length:DB.conversations.filter(c=>c.channel===v).length]), tab)}
    <div class="ibx" style="grid-template-columns:minmax(260px,380px) minmax(0,1fr)"><div class="ibx-l"><div style="padding:10px;border-bottom:1px solid var(--line);position:sticky;top:0;background:var(--surface);z-index:1">${searchBox('comms','Search conversations…')}</div>${rows.map(cv=>{ const l=cv.messages[cv.messages.length-1]; const c=get.client(cv.clientId); return `<div class="ibx-m ${sel&&cv.id===sel.id?'on':''}" data-a="convSel" data-id="${cv.id}">${srcIcon(cv.channel)}<div class="grow" style="min-width:0"><div class="row between"><span class="nm">${esc(c.name)}</span><span class="tm">${rel(l.at)}</span></div><div class="small trunc" style="color:var(--fg-2)">${esc(cv.subject)}</div><div class="pv">${esc(l.from)}: ${esc(l.body)}</div><div class="row mt-8" style="gap:6px">${badge(cv.followUp, cv.followUp==='Overdue'?'red':cv.followUp==='Done'?'green':cv.followUp==='Awaiting client'?'amber':'blue')}${cv.projectId?`<span class="tag mono">${cv.projectId}</span>`:''}<span style="margin-left:auto">${av(cv.assigned,'sm')}</span></div></div></div>`; }).join('') || empty('messages-square','No conversations','')}</div>
    <div class="ibx-d" style="padding:18px 20px">${sel?threadHtml(sel):empty('messages-square','Select a conversation','')}</div></div></div>`;
  return {html, crumbs:[['Communications']], title:'Communications'};
};
A.convSel = d => { setv('convSel', d.id, false); rerender(); };
A.openConv = d => { if(ROUTE.page==='comms'){ return A.convSel(d); } drawer({size:'wide', title:()=>esc(get.conv(d.id).subject), render:()=>threadHtml(get.conv(d.id))}); };
A.convFollow = (v,d) => { get.conv(d.id).followUp=v; commit('Follow-up status updated'); };
A.sendReply = d => { const cv=get.conv(d.id); const t=val('rp-'+d.id); if(!t) return toast('Write a reply first','err'); cv.messages.push({from:me().name, at:nowStamp(), body:t, attachments:[], sim:true}); cv.followUp='Awaiting client'; get.client(cv.clientId).lastContact=TODAY; log(`Replied on “${esc(cv.subject)}”`, cv.clientId, 'comms', cv.channel); commit('Reply saved to history'); };
A.aiReply = d => { const cv=get.conv(d.id); const c=get.client(cv.clientId); const last=cv.messages[cv.messages.length-1]; const ta=document.getElementById('rp-'+d.id); if(ta){ ta.value = `Hi ${c.contact.replace(/^Dr\s+/,'').split(' ')[0]},\n\nThanks for your message${last.from!==me().name?'':' — just following up'}. ${cv.followUp==='Overdue'?'This is now holding up the project timeline, so could we set up a 15-minute call this week to resolve it?':'I will confirm the next steps by tomorrow.'}\n\nKind regards,\n${me().name}`; ta.focus(); toast('AI draft inserted — review before sending','info'); } };
A.compose = d => { d=d||{}; closePop(); const c = d.client ? get.client(d.client) : null;
  modal({title:'Log a message', size:'lg', body:`<div class="form-grid">${field('Channel',`<select class="sel" id="cm-ch">${opts([['email','Email'],['whatsapp','WhatsApp'],['note','Internal note']],'email')}</select>`)}${field('Client *',`<select class="sel" id="cm-client" data-ch="cmClient">${clientOpts(d.client||'','Select client')}</select>`)}${field('To',`<input class="inp" id="cm-to" value="${esc(d.to||(c?c.email:''))}">`)}${field('Related project',`<select class="sel" id="cm-proj">${opts(DB.projects.filter(p=>!c||p.clientId===c.id).map(p=>[p.id,p.name]), '', {blank:'None'})}</select>`)}${field('Subject *',`<input class="inp" id="cm-subj" value="${esc(d.subject||'')}">`,'span2')}${field('Message *',`<textarea class="ta" id="cm-body" style="min-height:160px">${esc(d.body||'')}</textarea>`,'span2')}</div><div class="callout mt-12">${ic('info',15)}<span>This records the message in the client's history. Send it from your own email or WhatsApp — sending directly from here needs the email and WhatsApp integrations.</span></div>`, foot:`<button class="btn ghost" data-a="closeTop">Cancel</button><button class="btn pri" data-a="sendCompose">${ic('check',14)}Save to history</button>`}); };
A.cmClient = v => { const c=get.client(v); const to=document.getElementById('cm-to'); if(c && to) to.value = val('cm-ch')==='whatsapp'?c.whatsapp:c.email; const pr=document.getElementById('cm-proj'); if(pr) pr.innerHTML = opts(DB.projects.filter(p=>p.clientId===v).map(p=>[p.id,p.name]),'',{blank:'None'}); };
A.sendCompose = () => { if(!requireFields([['cm-client','Client'],['cm-subj','Subject'],['cm-body','Message']])) return; const c=get.client(val('cm-client')); const cv = {id:nextId('CV-',DB.conversations), clientId:c.id, channel:val('cm-ch'), subject:val('cm-subj'), participants:[c.contact, me().name], assigned:DB.me, projectId:val('cm-proj')||null, followUp:val('cm-ch')==='note'?'Done':'Awaiting client', messages:[{from:me().name, at:nowStamp(), body:val('cm-body'), attachments:[], sim:val('cm-ch')!=='note'}]}; DB.conversations.unshift(cv); c.lastContact=TODAY; log(`${CH_LABEL[cv.channel]} sent: “${esc(cv.subject)}”`, c.id, 'comms', cv.channel); closeTop(); setv('convSel', cv.id, false); setv('ctabc','all'); save(); go('comms'); toast('Message saved to history'); };

/* ===================== DOCUMENTS ===================== */
const FOLDERS = [['all','All documents','folder-open'],['Clients','Clients','building-2'],['Projects','Projects','folder-kanban'],['Quotes','Quotes','file-text'],['Invoices','Invoices','receipt'],['Agreements','Agreements','file-signature'],['Assessments','Assessments','compass'],['Technical documentation','Technical documentation','file-code-2'],['SOPs','SOPs','list-ordered'],['Internal','Internal company','lock']];
const FT_IC = {PDF:['file-text','var(--red)'],DOCX:['file-type-2','var(--blue)'],XLSX:['file-spreadsheet','var(--green)'],MD:['file-code-2','var(--fg-2)'],PNG:['file-image','var(--c6)']};
function docTable(docs, key){
  return table({key, rows:docs, act:x=>`data-a="previewDoc" data-id="${x.id}"`, emptyMsg:empty('folder-open','No documents','Upload a file to get started.'), cols:[
    {k:'name',l:'File name',r:x=>{ const [i,c]=FT_IC[x.type]||['file','var(--fg-3)']; return `<div class="row"><span style="color:${c}">${ic(i,17)}</span><span class="cell-t trunc" style="max-width:320px">${esc(x.name)}</span></div>`; }},
    {k:'type',l:'Type',r:x=>`<span class="tag">${x.type}</span>`},
    {k:'clientId',l:'Client',r:x=>x.clientId?esc(get.client(x.clientId).name):'<span class="muted">Internal</span>',sv:x=>x.clientId?get.client(x.clientId).name:'~'},
    {k:'projectId',l:'Project',r:x=>x.projectId?`<span class="mono small">${x.projectId}</span>`:'<span class="muted">—</span>'},
    {k:'owner',l:'Owner',r:x=>who(x.owner),sv:x=>uname(x.owner)},
    {k:'uploaded',l:'Uploaded',r:x=>fmtD(x.uploaded)},
    {k:'version',l:'Version'},
    {k:'access',l:'Access',r:x=>badge(x.access, x.access==='Restricted'?'red':x.access==='Client shared'?'cyan':'gray')},
    {k:'size',l:'Size',cls:'r'}
  ]});
}
window.docTable = docTable;
Views.docs = id => {
  const f = uv('docF','all'); const q=(UI.q.docs||'').toLowerCase();
  const inF = x => f==='all' || (f==='Clients'?!!x.clientId:f==='Projects'?(!!x.projectId||x.category==='Projects'):x.category===f);
  const rows = DB.documents.filter(x=>inF(x) && (!q || [x.name, x.clientId?get.client(x.clientId).name:''].join(' ').toLowerCase().includes(q)));
  const html = `<div class="page full">${pageHead('Documents & Knowledge', 'Quotes, agreements, assessments, technical documentation and SOPs in one place.', `<button class="btn pri" data-a="uploadDoc">${ic('upload',14)}Upload</button>`)}
    <div class="split" style="grid-template-columns:240px minmax(0,1fr)"><div class="card"><div class="card-b subnav" style="padding:8px">${FOLDERS.map(([v,l,i])=>`<button class="${f===v?'on':''}" data-a="seg" data-key="docF" data-v="${v}">${ic(i,15)}<span class="grow">${l}</span><span class="muted xs">${DB.documents.filter(x=>v==='all'||(v==='Clients'?!!x.clientId:v==='Projects'?(!!x.projectId||x.category==='Projects'):x.category===v)).length}</span></button>`).join('')}</div></div>
    <div><div class="toolbar">${searchBox('docs','Search documents…')}<span class="spacer"></span><span class="muted small">${rows.length} files</span></div>${card(null, docTable(rows,'docs'), {flush:true})}</div></div></div>`;
  if(id && get.doc(id)) after(()=>{ if(!STACK.length) A.previewDoc({id}); });
  return {html, crumbs:[['Documents','docs']], title:'Documents'};
};
/* File contents live in IndexedDB (browser file storage); records live with the rest of the data. */
const FILES = {
  db:null,
  open(){ return this.db ? Promise.resolve(this.db) : new Promise((res,rej)=>{ try { const r = indexedDB.open('ikusasa-files',1); r.onupgradeneeded = ()=>r.result.createObjectStore('f'); r.onsuccess = ()=>{ this.db=r.result; res(this.db); }; r.onerror = ()=>rej(r.error); } catch(e){ rej(e); } }); },
  put(k,blob){ return this.open().then(db=>new Promise((res,rej)=>{ const t=db.transaction('f','readwrite'); t.objectStore('f').put(blob,k); t.oncomplete=()=>res(); t.onerror=()=>rej(t.error); })); },
  get(k){ return this.open().then(db=>new Promise((res,rej)=>{ const r=db.transaction('f').objectStore('f').get(k); r.onsuccess=()=>res(r.result||null); r.onerror=()=>rej(r.error); })); },
  del(k){ return this.open().then(db=>new Promise(res=>{ const t=db.transaction('f','readwrite'); t.objectStore('f').delete(k); t.oncomplete=()=>res(); })); }
};
window.FILES = FILES;
const fmtSize = n => n>1e6?(n/1e6).toFixed(1)+' MB':Math.max(1,Math.round(n/1e3))+' KB';
A.previewDoc = d => { const x=get.doc(d.id); const c=x.clientId&&get.client(x.clientId); const p=x.projectId&&get.project(x.projectId);
  const vers = x.versions || [];
  const e = modal({title:esc(x.name), size:'xl', body:`<div class="grid" style="grid-template-columns:minmax(0,1fr) 270px;align-items:start" id="dv-grid"><div class="fpv" id="dv-prev" style="overflow:auto;min-height:420px;display:flex;align-items:center;justify-content:center">${x.blobKey?'<div class="col" style="align-items:center;gap:8px"><div class="skel" style="width:220px"></div><span class="muted small">Loading file…</span></div>':x.url?`<div class="empty">${ic('link',22)}<b>Stored as a link</b><p><a href="${esc(x.url)}" target="_blank" rel="noopener">${esc(x.url)}</a></p></div>`:empty('file','No file attached','This record has no stored file or link.')}</div>
    <div class="col gap-16"><dl class="kv" style="grid-template-columns:90px 1fr"><dt>Type</dt><dd>${x.type} · ${x.size}</dd><dt>Category</dt><dd>${esc(x.category)}</dd><dt>Client</dt><dd>${c?`<a href="#client-${c.id}">${esc(c.name)}</a>`:'Internal'}</dd><dt>Project</dt><dd>${p?`<a href="#project-${p.id}">${esc(p.name)}</a>`:'—'}</dd><dt>Owner</dt><dd>${who(x.owner)}</dd><dt>Uploaded</dt><dd>${fmtD(x.uploaded)}</dd><dt>Version</dt><dd>${x.version}</dd></dl>
    ${field('Access',`<select class="sel" data-ch="docAccess" data-id="${x.id}">${opts(['Internal','Client shared','Restricted'],x.access)}</select>`)}
    <div class="col" style="gap:6px">${x.blobKey?`<button class="btn sm" data-a="openFile" data-k="${x.blobKey}" data-n="${esc(x.name)}">${ic('external-link',13)}Open / download</button>`:''}<button class="btn sm" data-a="uploadDoc" data-version="${x.id}">${ic('upload',13)}Upload new version</button><button class="btn sm danger" data-a="delDoc" data-id="${x.id}">${ic('trash-2',13)}Delete</button></div>
    <div><div class="eyebrow" style="margin-bottom:6px">Version history</div><div class="col" style="gap:6px">${(vers.length?vers:[{v:x.version, date:x.uploaded, by:x.owner, size:x.size}]).slice().reverse().map(v=>`<div class="row between small"><span class="mono">${esc(v.v)}</span><span class="muted">${fmtD(v.date)} · ${esc((get.user(v.by)||{name:''}).name.split(' ')[0])}</span>${v.blobKey&&v.blobKey!==x.blobKey?`<button class="btn ghost xs" data-a="openFile" data-k="${v.blobKey}" data-n="${esc(x.name)}">Open</button>`:''}</div>`).join('')}</div></div></div></div>`, foot:`<button class="btn" data-a="closeTop">Close</button>`});
  if(window.innerWidth<900) setTimeout(()=>{ const g=document.getElementById('dv-grid'); if(g) g.style.gridTemplateColumns='minmax(0,1fr)'; },0);
  if(x.blobKey) FILES.get(x.blobKey).then(b=>{ const el=document.getElementById('dv-prev'); if(!el) return; if(!b){ el.innerHTML = empty('file-x','File not found in this browser','The record exists but the file is stored in another browser or was cleared. Upload it again as a new version.'); return; } const u = URL.createObjectURL(b);
    if(/^image\//.test(b.type)) el.innerHTML = `<img src="${u}" alt="${esc(x.name)}" style="max-width:100%;border-radius:6px">`;
    else if(b.type==='application/pdf') el.innerHTML = `<object data="${u}" type="application/pdf" style="width:100%;height:560px"><p class="muted small">This viewer cannot show PDFs inline. Use Open / download.</p></object>`;
    else if(/^text\//.test(b.type) || /\.(md|txt|csv|json)$/i.test(x.name)) b.text().then(t=>{ el.innerHTML = `<pre style="white-space:pre-wrap;font-family:var(--mono);font-size:12px;width:100%;margin:0;align-self:flex-start">${esc(t.slice(0,60000))}</pre>`; });
    else el.innerHTML = empty('file','No inline preview for this file type','Use Open / download to view it.');
  }).catch(()=>{ const el=document.getElementById('dv-prev'); if(el) el.innerHTML = empty('alert-triangle','Browser file storage is unavailable',''); });
};
A.openFile = d => FILES.get(d.k).then(b=>{ if(!b) return toast('File not found in this browser','err'); const u=URL.createObjectURL(b); const a=document.createElement('a'); a.href=u; a.download=d.n||'file'; a.target='_blank'; a.rel='noopener'; document.body.append(a); a.click(); a.remove(); setTimeout(()=>URL.revokeObjectURL(u), 60000); });
A.docAccess = (v,d) => { get.doc(d.id).access=v; log(`Access for ${esc(get.doc(d.id).name)} set to ${esc(v)}`, get.doc(d.id).clientId, 'docs-'+d.id, 'note'); save(); toast('Access set to '+v); };
A.delDoc = d => { closeAll(); confirmBox({title:'Delete document?', text:'The record and every stored version of the file are permanently removed from this browser.', ok:'Delete', danger:true, onOk:()=>{ const x=get.doc(d.id); (x.versions||[]).forEach(v=>v.blobKey&&FILES.del(v.blobKey)); if(x.blobKey) FILES.del(x.blobKey); DB.documents = DB.documents.filter(y=>y.id!==d.id); log(`Deleted document ${esc(x.name)}`, x.clientId, 'docs', 'note'); commit('Document deleted'); }}); };
let UPLOAD_FILE = null;
A.uploadDoc = d => { d=d||{}; UPLOAD_FILE=null; const base = d.version ? get.doc(d.version) : null; closeAll();
  modal({title:base?'New version · '+esc(base.name):'Upload document', body:`<label class="col" style="border:1.5px dashed var(--line-2);border-radius:10px;padding:22px;align-items:center;gap:6px;cursor:pointer;text-align:center" for="ud-file">${ic('upload-cloud',26,'muted')}<b>Choose a file</b><span class="muted small" id="ud-info">Stored in this browser's file storage (up to about 25 MB per file).</span><input type="file" id="ud-file" style="display:none" data-ch="udFile"></label>
    ${base?'':`<div class="form-grid mt-16">${field('File name *',`<input class="inp" id="ud-name" placeholder="e.g. Signed SOW.pdf">`,'span2')}${field('…or a link instead (SharePoint, Google Drive)',`<input class="inp" id="ud-url" placeholder="https://…">`,'span2')}${field('Category',`<select class="sel" id="ud-cat">${opts(FOLDERS.slice(3).map(f=>f[0]).concat(['Projects']), d.project?'Projects':'Technical documentation')}</select>`)}${field('Access',`<select class="sel" id="ud-acc">${opts(['Internal','Client shared','Restricted'],'Internal')}</select>`)}${field('Client',`<select class="sel" id="ud-client">${clientOpts(d.client||'','Internal (no client)')}</select>`)}${field('Project',`<select class="sel" id="ud-proj">${opts(DB.projects.map(p=>[p.id,p.name]), d.project||'', {blank:'None'})}</select>`)}</div>`}`, foot:`<button class="btn ghost" data-a="closeTop">Cancel</button><button class="btn pri" data-a="saveDoc" ${base?`data-version="${base.id}"`:''}>${ic('upload',14)}${base?'Upload version':'Save'}</button>`}); };
A.udFile = (v, d, el) => { const f = el.files && el.files[0]; if(!f) return; if(f.size>25e6){ toast('Files over 25 MB should be stored as a link instead','err'); el.value=''; return; } UPLOAD_FILE = f; const n=document.getElementById('ud-name'); if(n && !n.value) n.value = f.name; const i=document.getElementById('ud-info'); if(i) i.textContent = f.name+' · '+fmtSize(f.size); };
A.saveDoc = async d => {
  const base = d.version ? get.doc(d.version) : null;
  if(base){ if(!UPLOAD_FILE) return toast('Choose a file first','err'); const nv = 'v'+(+base.version.slice(1)+1); const key = base.id+'@'+nv; try { await FILES.put(key, UPLOAD_FILE); } catch(e){ return toast('Could not store the file in this browser','err'); } base.versions = base.versions || [{v:base.version, date:base.uploaded, by:base.owner, size:base.size, blobKey:base.blobKey||null}]; base.versions.push({v:nv, date:TODAY, by:DB.me, size:fmtSize(UPLOAD_FILE.size), blobKey:key}); Object.assign(base, {version:nv, blobKey:key, size:fmtSize(UPLOAD_FILE.size), uploaded:TODAY}); log(`Uploaded ${nv} of <b>${esc(base.name)}</b>`, base.clientId, 'docs-'+base.id, 'note'); closeTop(); commit('New version uploaded'); return; }
  const url = val('ud-url'); if(!UPLOAD_FILE && !url) return toast('Choose a file or enter a link','err'); if(!requireFields([['ud-name','File name']])) return;
  const n=val('ud-name'); const ext=(n.split('.').pop()||'').toUpperCase(); const id = nextId('F-',DB.documents); let key=null;
  if(UPLOAD_FILE){ key = id+'@v1'; try { await FILES.put(key, UPLOAD_FILE); } catch(e){ return toast('Could not store the file in this browser — save it as a link instead','err'); } }
  const x={id, name:n, type:FT_IC[ext]?ext:(UPLOAD_FILE?ext||'FILE':'LINK'), category:val('ud-cat'), clientId:val('ud-client')||null, projectId:val('ud-proj')||null, owner:DB.me, uploaded:TODAY, version:'v1', access:val('ud-acc'), size:UPLOAD_FILE?fmtSize(UPLOAD_FILE.size):'Link', blobKey:key, url:url||null, versions:[{v:'v1', date:TODAY, by:DB.me, size:UPLOAD_FILE?fmtSize(UPLOAD_FILE.size):'Link', blobKey:key}]};
  DB.documents.unshift(x); UPLOAD_FILE=null; log(`Added document <b>${esc(n)}</b>`, x.clientId, 'docs-'+x.id, 'note'); closeTop(); commit('Document saved'); };

/* ===================== INTEGRATIONS ===================== */
Views.integrations = () => {
  const ws = DB.workflows; const conn = DB.integrations.filter(i=>i.status==='Connected').length;
  const html = `<div class="page full">${pageHead('Integrations & Automation', 'The connections and n8n workflows that run the business — and the systems you build for clients.', `<button class="btn pri" data-a="newWorkflow">${ic('plus',14)}Register workflow</button>`)}
    <div class="callout" style="margin-bottom:16px">${ic('info',16)}<span>This app does not connect to these services by itself yet. Use the cards to record each connection's status as you set it up, and register your n8n workflows below so failures and run history are tracked in one place. Live syncing needs the Supabase back end.</span></div>
    <div class="grid g4">${DB.integrations.map(i=>`<div class="int"><div class="int-h"><span class="int-ic">${ic(i.icon,18)}</span><div class="grow"><div class="strong">${esc(i.name)}</div><div class="muted xs">${esc(i.desc)}</div></div>${badge(i.status, i.status==='Connected'?'green':i.status==='Error'?'red':i.status==='In setup'?'amber':'gray')}</div><div class="stats"><div><div class="k">Last successful sync</div>${i.lastSync?fmtDT(i.lastSync):'—'}</div><div><div class="k">Workflows</div>${ws.filter(w=>w.integration===i.name).length}</div><div style="grid-column:1/-1"><div class="k">Last error</div><span class="${i.lastError&&i.lastError!=='—'?'down':''}">${esc(i.lastError||'—')}</span></div><div style="grid-column:1/-1"><div class="k">Notes</div>${esc(i.usage||'—')}</div></div><button class="btn sm" data-a="configInt" data-id="${i.id}">${ic('settings-2',13)}Update status</button></div>`).join('')}</div>
    <div class="section-t">Automation monitoring</div>
    <div class="kpis" style="grid-template-columns:repeat(4,minmax(0,1fr));margin-bottom:14px">${kpiCell({l:'Connections',v:conn+' / '+DB.integrations.length,d:'Marked as connected'})}${kpiCell({l:'Workflows',v:ws.length,d:`${ws.filter(w=>w.status==='Active').length} active`})}${kpiCell({l:'Failing',v:ws.filter(w=>w.status==='Error').length,d:ws.filter(w=>w.status==='Error').map(w=>w.id).join(', ')||'None',tone:ws.some(w=>w.status==='Error')?'down':''})}${kpiCell({l:'Logged errors',v:sum(ws,w=>w.errors||0),d:'Across all workflows'})}</div>
    ${card(null, table({key:'wf', rows:ws, act:w=>`data-a="openWf" data-id="${w.id}"`, emptyMsg:empty('workflow','No workflows registered','Register each n8n workflow (intake, invoicing reminders, client automations) to monitor it here.',`<button class="btn sm pri" data-a="newWorkflow">${ic('plus',13)}Register workflow</button>`), cols:[
      {k:'name',l:'Workflow',r:w=>`<div class="cell-t">${esc(w.name)}</div><div class="cell-s mono">${w.id} · ${esc(w.integration)}</div>`},{k:'trigger',l:'Trigger',r:w=>`<span class="small">${esc(w.trigger)}</span>`},{k:'status',l:'Status',r:w=>badge(w.status)},{k:'lastRun',l:'Last execution',r:w=>w.lastRun?rel(w.lastRun):'<span class="muted">Never</span>',sv:w=>w.lastRun||''},{k:'result',l:'Result',r:w=>`<span class="${/^Fail/.test(w.result)?'down':w.result==='Success'?'up':'muted'} small">${esc(w.result)}</span>`},{k:'errors',l:'Errors',cls:'r',r:w=>`<span class="num ${w.errors?'down':''}">${w.errors||0}</span>`},{k:'runs',l:'Logged runs',cls:'r',r:w=>`<span class="num">${(w.history||[]).length}</span>`},{k:'process',l:'Related process',r:w=>`<span class="tag">${esc(w.process)}</span>`}
    ]}), {flush:true})}</div>`;
  return {html, crumbs:[['Integrations']], title:'Integrations'};
};
function wfForm(w){ return `<div class="form-grid">${field('Workflow name *',`<input class="inp" id="wf-name" value="${esc(w.name||'')}" placeholder="e.g. Inbound email → enquiry intake">`,'span2')}${field('Trigger',`<input class="inp" id="wf-trig" value="${esc(w.trigger||'')}" placeholder="e.g. Webhook, daily 08:00">`)}${field('Integration',`<select class="sel" id="wf-int">${opts(DB.integrations.map(i=>i.name), w.integration||'n8n')}</select>`)}${field('Related process',`<select class="sel" id="wf-proc">${opts(['Intake','Commercial','Finance','Delivery','Client system','Internal'], w.process||'Intake')}</select>`)}${field('Status',`<select class="sel" id="wf-status">${opts(['Draft','Active','Paused','Error'], w.status||'Draft')}</select>`)}${field('Client (for client systems)',`<select class="sel" id="wf-client">${clientOpts(w.clientId||'','Internal')}</select>`)}${field('n8n workflow URL',`<input class="inp" id="wf-url" value="${esc(w.url||'')}" placeholder="https://…">`)}</div>`; }
A.newWorkflow = () => modal({title:'Register workflow', size:'lg', body:wfForm({}), foot:`<button class="btn ghost" data-a="closeTop">Cancel</button><button class="btn pri" data-a="saveWorkflow">Register</button>`});
A.editWorkflow = d => { const w=get.wf(d.id); modal({title:'Edit '+w.id, size:'lg', body:wfForm(w), foot:`<button class="btn danger" data-a="delWorkflow" data-id="${w.id}" style="margin-right:auto">${ic('trash-2',14)}Delete</button><button class="btn ghost" data-a="closeTop">Cancel</button><button class="btn pri" data-a="saveWorkflow" data-id="${w.id}">Save</button>`}); };
A.saveWorkflow = d => { if(!requireFields([['wf-name','Workflow name']])) return; let w = d.id ? get.wf(d.id) : {id:nextId('W-',DB.workflows), lastRun:null, result:'Not run', errors:0, history:[]}; Object.assign(w,{name:val('wf-name'), trigger:val('wf-trig')||'—', integration:val('wf-int'), process:val('wf-proc'), status:val('wf-status'), clientId:val('wf-client')||null, url:val('wf-url')}); if(!d.id) DB.workflows.push(w); closeTop(); commit(d.id?'Workflow updated':'Workflow registered'); };
A.delWorkflow = d => { closeAll(); confirmBox({title:'Delete workflow record?', text:'This removes the workflow and its logged runs from monitoring. The workflow in n8n is not affected.', ok:'Delete', danger:true, onOk:()=>{ DB.workflows = DB.workflows.filter(w=>w.id!==d.id); commit('Workflow removed'); }}); };
A.openWf = d => drawer({size:'wide', title:()=>esc(get.wf(d.id).name), render:()=>{ const w=get.wf(d.id); const runs=w.history||[];
  return `<div class="col gap-16"><div class="row wrap">${badge(w.status)}<span class="muted small">${w.id} · ${esc(w.integration)} · ${esc(w.process)}</span><button class="btn ghost xs" data-a="editWorkflow" data-id="${w.id}" style="margin-left:auto">${ic('pen-line',12)}Edit</button></div><dl class="kv"><dt>Trigger</dt><dd>${esc(w.trigger)}</dd><dt>Client</dt><dd>${w.clientId&&get.client(w.clientId)?`<a href="#client-${w.clientId}">${esc(get.client(w.clientId).name)}</a>`:'Internal'}</dd><dt>Last execution</dt><dd>${w.lastRun?fmtDT(w.lastRun):'Never'}</dd><dt>Last result</dt><dd>${esc(w.result)}</dd>${w.url?`<dt>n8n</dt><dd><a href="${esc(w.url)}" target="_blank" rel="noopener">${esc(w.url)}</a></dd>`:''}</dl>
    ${card('Log an execution', `<p class="muted small" style="margin-bottom:10px">Until n8n reports runs automatically, record notable executions — especially failures — here.</p><div class="form-grid">${field('Result',`<select class="sel" id="wr-ok">${opts([['1','Success'],['0','Failed']],'1')}</select>`)}${field('When',`<input class="inp" type="datetime-local" id="wr-at" value="${nowStamp()}">`)}${field('Error / note',`<input class="inp" id="wr-err" placeholder="e.g. API returned 429">`,'span2')}</div><div class="row mt-12" style="justify-content:flex-end"><button class="btn pri sm" data-a="logRun" data-id="${w.id}">${ic('plus',13)}Log run</button></div>`)}
    ${card('Execution history', runs.length?`<div class="tw"><table class="tbl"><thead><tr><th>When</th><th>Result</th><th>Error / note</th><th>Logged by</th></tr></thead><tbody>${runs.map(r=>`<tr><td>${fmtDT(r.at)}</td><td>${badge(r.ok?'Success':'Failed')}</td><td class="small ${r.ok?'muted':'down'}">${esc(r.err||'—')}</td><td>${who(r.by)}</td></tr>`).join('')}</tbody></table></div>`:empty('history','No runs logged',''), {flush:true})}</div>`; }});
A.logRun = d => { const w=get.wf(d.id); const ok = val('wr-ok')==='1'; const at = (val('wr-at')||nowStamp()).slice(0,16); w.history = [{at, ok, err:val('wr-err'), by:DB.me}].concat(w.history||[]).sort((a,b)=>b.at.localeCompare(a.at)); if(!w.lastRun || at>=w.lastRun){ w.lastRun=at; w.result = ok?'Success':'Failed'+(val('wr-err')?' — '+val('wr-err'):''); } if(!ok){ w.errors=(w.errors||0)+1; w.status='Error'; notify('error', `Workflow ${w.id} failed: ${val('wr-err')||'see log'}`, 'integrations'); } else if(w.status==='Error') w.status='Active'; commit('Run logged'); };
A.configInt = d => { const i=DB.integrations.find(x=>x.id===d.id);
  modal({title:'Update '+esc(i.name), body:`<div class="callout" style="margin-bottom:14px">${ic('lock',15)}<span>Never paste passwords, API keys or tokens into this app — it stores data in the browser. Keep credentials in n8n or Supabase Vault.</span></div><div class="form-grid">${field('Status',`<select class="sel" id="ci-st">${opts(['Not connected','In setup','Connected','Error'], i.status)}</select>`)}${field('Last successful sync',`<input class="inp" type="datetime-local" id="ci-sync" value="${i.lastSync||''}">`)}${field('Last error',`<input class="inp" id="ci-err" value="${esc(i.lastError==='—'?'':i.lastError||'')}">`,'span2')}${field('Notes (account, owner, usage)',`<input class="inp" id="ci-use" value="${esc(i.usage==='—'?'':i.usage||'')}">`,'span2')}</div>`, foot:`<button class="btn ghost" data-a="closeTop">Cancel</button><button class="btn pri" data-a="saveInt" data-id="${i.id}">Save</button>`}); };
A.saveInt = d => { const i=DB.integrations.find(x=>x.id===d.id); Object.assign(i,{status:val('ci-st'), lastSync:val('ci-sync')||null, lastError:val('ci-err')||'—', usage:val('ci-use')||'—'}); log(`${esc(i.name)} integration marked ${esc(i.status)}`, null, 'integrations', 'status'); closeTop(); commit('Integration updated'); };

/* ===================== ANALYTICS ===================== */
Views.analytics = () => {
  const tab = uv('atab','sales'); const range = uv('arange','12'); const all = calc.monthly(12); const mons = all.slice(-(+range)); const drill = UI.v.drill;
  const YEAR = TODAY.slice(0,4); const ytd = all.filter(m=>m.m.startsWith(YEAR));
  const nd = (m,i) => empty(i||'bar-chart-3','No data yet',m);
  let body = '';
  if(tab==='sales'){
    const totE = sum(mons,m=>m.enquiries); const dec = DB.quotes.filter(q=>['Accepted','Rejected','Expired'].includes(q.status)); const acc = DB.quotes.filter(q=>q.status==='Accepted');
    const f = calc.funnel(); const conv = f[0].value ? pct(f[4].value, DB.clients.length||f[0].value) : 0;
    const sources = uniq(DB.clients.map(c=>c.source||'Other')).map(s=>{ const cs = DB.clients.filter(c=>(c.source||'Other')===s); const won = cs.filter(c=>DB.quotes.some(q=>q.clientId===c.id&&q.status==='Accepted')); return {s, n:cs.length, share:pct(cs.length, DB.clients.length), conv:pct(won.length, cs.length), rev:sum(cs,c=>calc.ltv(c))}; }).sort((a,b)=>b.n-a.n);
    const di = drill && drill.t==='enq' ? drill.i : undefined; const dm = di!==undefined ? mons[di].m : null;
    body = `<div class="kpis" style="grid-template-columns:repeat(4,1fr);margin-bottom:16px">${kpiCell({l:'Enquiries',v:totE,d:`Last ${range} months`})}${kpiCell({l:'Lead conversion',v:conv+'%',d:'Clients with an accepted quote'})}${kpiCell({l:'Quote acceptance rate',v:dec.length?pct(acc.length,dec.length)+'%':'—',d:`${acc.length} of ${dec.length} decided`})}${kpiCell({l:'Average deal size',v:acc.length?fmtRk(sum(acc,q=>calc.quote(q).sub)/acc.length):'—',d:'Accepted quotes, ex VAT'})}</div>
      <div class="grid g-21">${card('Enquiry volume', totE?chBars({labels:mons.map(m=>fmtM(m.m).slice(0,3)), series:[{name:'Enquiries',values:mons.map(m=>m.enquiries),color:'var(--c1)'}], fmt:v=>Math.round(v), h:220, hl:di, act:(i)=>`data-a="drill" data-t="enq" data-i="${i}"`}):nd('Logged enquiries per month.','inbox'), {hint:'Click a bar to drill down'})}
      ${card('Quote outcomes', DB.quotes.length?chDonut({items:[{label:'Accepted',value:acc.length,color:'var(--green)'},{label:'Awaiting',value:DB.quotes.filter(q=>['Sent','Viewed'].includes(q.status)).length,color:'var(--c2)'},{label:'In preparation',value:DB.quotes.filter(q=>['Draft','Internal review'].includes(q.status)).length,color:'var(--c5)'},{label:'Rejected',value:DB.quotes.filter(q=>q.status==='Rejected').length,color:'var(--red)'},{label:'Expired',value:DB.quotes.filter(q=>q.status==='Expired').length,color:'var(--amber)'}].filter(x=>x.value), fmt:v=>v, center:{v:DB.quotes.length,l:'quotes'}}):nd('Quotes by outcome.','file-text'))}</div>
      ${dm?`<div class="mt-16">${card(`Enquiries received in ${fmtM(dm)}`, (()=>{ const r = DB.enquiries.filter(e=>e.received.startsWith(dm)); return table({key:'drillE', rows:r, go:e=>'inbox-'+e.id, emptyMsg:empty('inbox','None this month',''), cols:[{k:'received',l:'Received',r:e=>fmtDT(e.received)},{k:'channel',l:'Channel',r:e=>srcIcon(e.channel)+' '+CH_LABEL[e.channel]},{k:'company',l:'Company',r:e=>`<span class="cell-t">${esc(e.company)}</span>`},{k:'cls',l:'Classification',r:e=>e.status==='Unprocessed'?'<span class="muted">Not processed</span>':esc(e.ai.cls),sort:false},{k:'status',l:'Status',r:e=>badge(e.status)}]}); })(), {flush:true, act:`<button class="btn ghost xs" data-a="drillClear">${ic('x',12)}Close</button>`})}</div>`:''}
      <div class="grid g2 mt-16">${card('Lead conversion funnel', f[0].value||DB.clients.length?chFunnel(f):nd('Enquiries through to paid clients.','filter'), {hint:'All time'})}
      ${card('Lead source performance', sources.length?`<div class="tw"><table class="tbl"><thead><tr><th>Source</th><th class="r">Clients</th><th class="r">Share</th><th class="r">Conversion</th><th class="r">Revenue</th><th style="width:26%"></th></tr></thead><tbody>${sources.map(x=>`<tr><td class="cell-t">${esc(x.s)}</td><td class="r num">${x.n}</td><td class="r num">${x.share}%</td><td class="r num">${x.conv}%</td><td class="r num">${fmtRk(x.rev)}</td><td><div class="pg"><i style="width:${x.conv}%"></i></div></td></tr>`).join('')}</tbody></table></div>`:nd('Set a lead source on each client.','share-2'), {flush:true, hint:'Revenue = payments received, ex VAT'})}</div>`;
  }
  if(tab==='delivery'){
    const done = DB.projects.filter(p=>p.status==='Completed'); const act = DB.projects.filter(p=>!['Completed','On hold'].includes(p.status));
    const withDate = done.filter(p=>p.completed); const onTime = withDate.filter(p=>p.completed<=p.target);
    const avgDays = withDate.length ? Math.round(sum(withDate,p=>days(p.start,p.completed))/withDate.length) : null;
    const reviewed = DB.projects.flatMap(p=>p.workstreams).filter(w=>w.reviewed||w.returned); const returned = DB.projects.flatMap(p=>p.workstreams).reduce((s,w)=>s+(w.returned||0),0);
    const statusCounts = STATUS.project.map(s=>({s, n:DB.projects.filter(p=>p.status===s).length})).filter(x=>x.n);
    const di = drill && drill.t==='pst' ? drill.i : undefined;
    const compByMonth = mons.map(m=>({m:m.m, on:withDate.filter(p=>p.completed.startsWith(m.m)&&p.completed<=p.target).length, late:withDate.filter(p=>p.completed.startsWith(m.m)&&p.completed>p.target).length}));
    body = `<div class="kpis" style="grid-template-columns:repeat(5,1fr);margin-bottom:16px">${kpiCell({l:'Completion rate',v:DB.projects.length?pct(done.length, DB.projects.length)+'%':'—',d:`${done.length} of ${DB.projects.length} projects`})}${kpiCell({l:'Average delivery time',v:avgDays!==null?avgDays+' days':'—',d:'Start to completion'})}${kpiCell({l:'On-time delivery',v:withDate.length?pct(onTime.length,withDate.length)+'%':'—',d:`${onTime.length} of ${withDate.length} completed on time`})}${kpiCell({l:'Blocked projects',v:DB.projects.filter(p=>p.status==='Blocked').length,d:'Need action',tone:DB.projects.some(p=>p.status==='Blocked')?'down':'',go:'projects'})}${kpiCell({l:'Rework rate',v:reviewed.length?pct(DB.projects.flatMap(p=>p.workstreams).filter(w=>w.returned).length, reviewed.length)+'%':'—',d:`${returned} change request${returned===1?'':'s'} on reviews`})}</div>
      <div class="grid g2">${card('Projects by status', statusCounts.length?chBars({labels:statusCounts.map(x=>x.s.replace('Awaiting ','Await. ').replace(' client feedback',' feedback')), series:[{name:'Projects',values:statusCounts.map(x=>x.n),color:'var(--c2)'}], fmt:v=>Math.round(v), h:230, hl:di, act:i=>`data-a="drill" data-t="pst" data-i="${i}"`}):nd('Projects grouped by status.','folder-kanban'), {hint:'Click to drill down'})}
      ${card('Completions per month', compByMonth.some(x=>x.on||x.late)?`<div class="legend" style="margin-bottom:8px"><span><i style="background:var(--c3)"></i>On time</span><span><i style="background:var(--red)"></i>Late</span></div>${chBars({labels:compByMonth.map(x=>fmtM(x.m).slice(0,3)), series:[{name:'On time',values:compByMonth.map(x=>x.on),color:'var(--c3)'},{name:'Late',values:compByMonth.map(x=>x.late),color:'var(--red)'}], stacked:true, fmt:v=>Math.round(v), h:230})}`:nd('Completed projects, on time vs late.','check-circle-2'))}</div>
      ${di!==undefined?`<div class="mt-16">${card(`Projects: ${statusCounts[di].s}`, table({key:'drillP', rows:DB.projects.filter(p=>p.status===statusCounts[di].s), go:p=>'project-'+p.id, cols:[{k:'name',l:'Project',r:p=>`<span class="cell-t">${esc(p.name)}</span>`},{k:'clientId',l:'Client',r:p=>esc(get.client(p.clientId).name)},{k:'pm',l:'PM',r:p=>who(p.pm)},{k:'target',l:'Target',r:p=>fmtD(p.target)},{k:'p',l:'Progress',r:p=>prog(calc.progress(p))}]}), {flush:true, act:`<button class="btn ghost xs" data-a="drillClear">${ic('x',12)}Close</button>`})}</div>`:''}
      <div class="mt-16">${card('Active project health', act.length?`<div class="tw"><table class="tbl"><thead><tr><th>Project</th><th>Workstreams</th><th>Progress</th><th>Schedule</th><th>Risk</th></tr></thead><tbody>${act.map(p=>{ const ws=p.workstreams; const st=['Done','In review','In progress','Blocked','Not started']; const col={'Done':'var(--green)','In review':'var(--blue)','In progress':'var(--c1)','Blocked':'var(--red)','Not started':'var(--surface-3)'}; return `<tr data-go="project-${p.id}"><td><span class="cell-t">${esc(p.name)}</span><div class="cell-s">${esc(get.client(p.clientId).name)}</div></td><td><div style="display:flex;height:10px;border-radius:3px;overflow:hidden;min-width:160px">${st.map(s=>{ const n=ws.filter(w=>w.status===s).length; return n?`<span style="flex:${n};background:${col[s]}" data-tip="${s}: ${n}"></span>`:''; }).join('')}</div></td><td style="min-width:140px">${prog(calc.progress(p))}</td><td>${until(p.target)<0?badge('Late','red'):until(p.target)<14?badge('Due soon','amber'):badge('On track','green')}</td><td>${badge(p.risk)}</td></tr>`; }).join('')}</tbody></table></div>`:nd('Active projects appear here.','folder-kanban'), {flush:true})}</div>`;
  }
  if(tab==='team'){
    const L = DB.users.map(u=>({u, l:calc.load(u)}));
    const depts = uniq(DB.users.map(u=>u.dept)).map(dp=>{ const us=DB.users.filter(u=>u.dept===dp); return {dp, util:Math.round(sum(us,u=>u.alloc)/Math.max(1,sum(us,u=>u.capacity))*100)}; });
    const od = DB.tasks.filter(t=>t.status!=='Done' && t.due && t.due<TODAY);
    const doneYear = DB.tasks.filter(t=>t.status==='Done').length;
    body = `<div class="kpis" style="grid-template-columns:repeat(4,1fr);margin-bottom:16px">${kpiCell({l:'Capacity utilisation',v:Math.round(sum(DB.users,u=>u.alloc)/Math.max(1,sum(DB.users,u=>u.capacity))*100)+'%',d:'Allocated / available hours'})}${kpiCell({l:'Tasks completed',v:doneYear,d:'All time'})}${kpiCell({l:'Overdue assignments',v:od.length,d:`${uniq(od.map(t=>t.assignee)).length} people affected`,tone:od.length?'down':''})}${kpiCell({l:'Over capacity',v:L.filter(x=>x.l.util>100).length,d:'People above 100%',tone:L.some(x=>x.l.util>100)?'warn':''})}</div>
      <div class="grid g2">${card('Workload', chHBar({items:L.sort((a,b)=>b.l.util-a.l.util).map(x=>({label:x.u.name, value:x.l.util, color:x.l.util>100?'var(--red)':x.l.util>90?'var(--amber)':'var(--c1)', marker:100, go:'team-'+x.u.id})), fmt:v=>v+'%', max:125}))}
      ${card('Tasks by person', DB.tasks.length?`<div class="legend" style="margin-bottom:8px"><span><i style="background:var(--c3)"></i>Completed</span><span><i style="background:var(--c4)"></i>Open</span></div>${chBars({labels:L.slice(0,10).map(x=>x.u.name.split(' ')[0]), series:[{name:'Completed',values:L.slice(0,10).map(x=>x.l.done),color:'var(--c3)'},{name:'Open',values:L.slice(0,10).map(x=>x.l.open),color:'var(--c4)'}], stacked:true, fmt:v=>Math.round(v), h:260})}`:nd('Open and completed tasks per person.','check-square'))}</div>
      <div class="grid g2 mt-16">${card('Capacity by department', chHBar({items:depts.map(x=>({label:x.dp, value:x.util, color:x.util>100?'var(--red)':'var(--c2)', marker:100})), fmt:v=>v+'%', max:120}))}
      ${card('Overdue assignments', table({key:'odt', rows:od, act:t=>`data-a="openTask" data-id="${t.id}"`, cols:[{k:'title',l:'Task',r:t=>`<span class="cell-t">${esc(t.title)}</span>`},{k:'assignee',l:'Owner',r:t=>who(t.assignee)},{k:'due',l:'Due',r:t=>`<span class="down">${dueTxt(t.due)}</span>`},{k:'status',l:'Status',r:t=>badge(t.status)}], emptyMsg:empty('check-circle-2','Nothing overdue','')}), {flush:true})}</div>`;
  }
  if(tab==='financial'){
    const invs = DB.invoices.map(i=>({i,c:calc.inv(i)})).filter(x=>x.c.outstanding>0);
    const ag = [['Current',x=>!x.c.overdue],['1–30 days',x=>x.c.overdue&&x.c.daysOver<=30],['31–60 days',x=>x.c.daysOver>30&&x.c.daysOver<=60],['60+ days',x=>x.c.daysOver>60]].map(([l,f])=>({l, v:sum(invs.filter(f),x=>x.c.outstanding), rows:invs.filter(f)}));
    const di = drill && drill.t==='age' ? drill.i : undefined;
    const revY = sum(ytd,m=>m.revenue), costY = sum(ytd,m=>m.costs);
    body = `<div class="kpis" style="grid-template-columns:repeat(4,1fr);margin-bottom:16px">${kpiCell({l:`Revenue (${YEAR} to date)`,v:fmtRk(revY),d:'Ex VAT',tone:'up'})}${kpiCell({l:'Outstanding debtors',v:fmtR(sum(invs,x=>x.c.outstanding)),d:`${invs.length} invoices`,tone:invs.length?'warn':''})}${kpiCell({l:'Monthly recurring revenue',v:fmtR(calc.mrr()),d:`${DB.retainers.filter(r=>!r.until||r.until>=TODAY).length} active retainers`})}${kpiCell({l:`Margin (${YEAR} to date)`,v:revY?pct(revY-costY, revY)+'%':'—',d:'Revenue less expenses'})}</div>
      <div class="grid g2">${card('Revenue', mons.some(m=>m.revenue||m.accepted)?chArea({labels:mons.map(m=>fmtM(m.m).slice(0,3)), series:[{name:'Revenue',values:mons.map(m=>m.revenue),color:'var(--c1)'},{name:'Accepted quotes',values:mons.map(m=>m.accepted),color:'var(--c2)'}], h:230}):nd('Revenue received and quotes accepted per month.','banknote'), {hint:'Ex VAT'})}
      ${card('Debtors ageing', invs.length?chBars({labels:ag.map(a=>a.l), series:[{name:'Outstanding',values:ag.map(a=>a.v),color:'var(--c4)'}], h:230, hl:di, act:i=>`data-a="drill" data-t="age" data-i="${i}"`}):nd('Unpaid invoices by how overdue they are.','hourglass'), {hint:'Click to see invoices'})}</div>
      ${di!==undefined?`<div class="mt-16">${card(`Outstanding · ${ag[di].l}`, table({key:'drillA', rows:ag[di].rows.map(x=>x.i), act:i=>`data-a="openInvoice" data-id="${i.id}"`, cols:invCols(), emptyMsg:empty('check-circle-2','Nothing in this bucket','')}), {flush:true, act:`<button class="btn ghost xs" data-a="drillClear">${ic('x',12)}Close</button>`})}</div>`:''}
      <div class="grid g2 mt-16">${card('Monthly recurring revenue', all.some(m=>m.mrr)?chArea({labels:all.map(m=>fmtM(m.m).slice(0,3)), series:[{name:'MRR',values:all.map(m=>m.mrr),color:'var(--c3)'}], h:210}):nd('Add retainers in Finance to track recurring revenue.','repeat'), {hint:'From retainers'})}
      ${card('Revenue by service type', DB.projects.some(p=>p.budget)?chDonut({items:STATUS.categories.map(c=>({label:c, value:sum(DB.projects.filter(p=>p.category===c),p=>p.budget), color:CAT_COLOR[c]})).filter(x=>x.value)}):nd('Project budgets by service type.','pie-chart'), {hint:'Contracted value'})}</div>`;
  }
  const html = `<div class="page full">${pageHead('Analytics', 'Sales, delivery, team and financial performance — calculated from your records. Click bars to drill down.', segc('arange',[['6','6M'],['12','12M']],range))}
    ${tabsc('atab', [['sales','Sales'],['delivery','Delivery'],['team','Team'],['financial','Financial']], tab)}<div class="tabpane">${body}</div></div>`;
  return {html, crumbs:[['Analytics']], title:'Analytics'};
};
A.drill = d => { const cur = UI.v.drill; UI.v.drill = cur && cur.t===d.t && cur.i===+d.i ? null : {t:d.t, i:+d.i}; rerender(); };
A.drillClear = () => { UI.v.drill=null; rerender(); };
const _seg = A.seg; A.seg = d => { if(d.key==='atab') UI.v.drill=null; _seg(d); };

/* ===================== NOTIFICATIONS ===================== */
Views.notifications = () => {
  const f = uv('nf','all'); const kf = UI.f.actK||'';
  const MY = DB.notifications.filter(mine); const list = MY.slice().sort((a,b)=>b.at.localeCompare(a.at)).filter(n=>f==='all'||(f==='unread'?!n.read:n.type===f));
  const kinds = uniq(DB.activity.map(a=>a.kind));
  const acts = DB.activity.filter(a=>!kf||a.kind===kf).slice(0,40);
  const html = `<div class="page">${pageHead('Notifications & Activity', 'What needs you, and what is happening across the business.', `<button class="btn" data-a="readAll">${ic('check-check',14)}Mark all read</button><button class="btn" data-a="go" data-to="admin">${ic('settings',14)}Preferences</button>`)}
    <div class="grid g2" style="align-items:start">
      <div>${tabsc('nf', [['all','All',MY.length],['unread','Unread',MY.filter(n=>!n.read).length],['reminder','Reminders'],['pool','Up for grabs'],['task','Tasks'],['overdue','Overdue'],['payment','Payments']], f)}${card(null, list.length?`<div class="list">${list.map(n=>`<div class="row" style="border-bottom:1px solid var(--line)"><div class="grow">${notifRow(n).replace('border-bottom','x')}</div><button class="ib sm" style="margin-right:10px" data-a="toggleRead" data-id="${n.id}" data-tip="${n.read?'Mark unread':'Mark read'}">${ic(n.read?'mail':'mail-open',14)}</button></div>`).join('')}</div>`:empty('bell-off','You are all caught up','No notifications in this view.'), {flush:true})}</div>
      <div><div class="tabs" style="margin-bottom:16px"><span class="tab on">Activity feed</span></div><div class="toolbar"><select class="sel sm" data-ch="filt" data-key="actK" aria-label="Activity type">${opts(kinds.map(k=>[k,k[0].toUpperCase()+k.slice(1)]), kf, {blank:'All activity'})}</select></div>${card(null, acts.map(feedItem).join('') || empty('activity','No activity',''), {flush:true})}</div>
    </div></div>`;
  return {html, crumbs:[['Notifications']], title:'Notifications'};
};
A.toggleRead = d => { const n=DB.notifications.find(x=>x.id===d.id); n.read=!n.read; commit(); };

/* ===================== ADMINISTRATION ===================== */
const PERMS = [['delete_data','Delete clients, tasks & other records'],['assign_tasks','Assign tasks to others'],['view_crm','View clients & CRM'],['edit_clients','Create & edit clients'],['create_quotes','Create quotes'],['send_quotes','Approve & send quotes'],['record_pay','Record payments'],['view_fin','View finance'],['auth_proj','Authorise projects'],['manage_tasks','Manage tasks'],['manage_team','Manage team'],['admin','Administration']];
const ROLES = ['Owner','Admin','Team leader','Sales','Delivery','Finance','Read-only'];
const DEFAULT_PERMS = {Owner:PERMS.map(p=>p[0]),Admin:PERMS.map(p=>p[0]),'Team leader':['assign_tasks','view_crm','edit_clients','create_quotes','send_quotes','view_fin','auth_proj','manage_tasks','manage_team'],Sales:['view_crm','edit_clients','create_quotes','send_quotes','manage_tasks'],Delivery:['view_crm','manage_tasks'],Finance:['view_crm','record_pay','view_fin','manage_tasks'],'Read-only':['view_crm']};
window.PERMS = PERMS; window.ROLES = ROLES; window.DEFAULT_PERMS = DEFAULT_PERMS;
const SW = (id, on, ch, extra='', disabled) => `<label class="switch"><input type="checkbox" id="${id}" ${on?'checked':''} data-ch="${ch}" ${extra} ${disabled?'disabled':''}><span></span></label>`;
const setRow = (t, s, ctl) => `<div class="row between" style="padding:12px 0;border-bottom:1px solid var(--line);gap:16px"><div><div class="strong small">${t}</div>${s?`<div class="muted small">${s}</div>`:''}</div>${ctl}</div>`;
const AUTH_NOTE = `<div class="callout mt-16">${ic('info',15)}<span>Sign-in, MFA, SSO and session rules take effect once accounts move to Supabase Auth. Until then anyone using this browser can open the workspace, so use it on a device only your team uses.</span></div>`;
const DEPTS = () => uniq(['Leadership','Client Success','Delivery','Engineering','Design','Finance'].concat(DB.users.map(u=>u.dept)));
Views.admin = () => {
  const sec = uv('adm','company'); const S = DB.settings; S.perms = S.perms || JSON.parse(JSON.stringify(DEFAULT_PERMS)); const C = S.company;
  const nav = [['company','Company details','building'],['users','Team members','users'],['roles','Roles & permissions','shield'],['teams','Departments','network'],['templates','Project types & templates','layout-template'],['workflow','Workflow & reminders','workflow'],['notif','Notifications','bell'],['security','Security','lock'],['audit','Audit log','scroll-text'],['data','Backup & data','database'],['appearance','Appearance','palette']];
  let body='';
  if(sec==='company') body = card('Company details', `<p class="sub small" style="margin-bottom:14px">Shown on quotes, invoices and the workspace switcher.</p><div class="form-grid">${field('Registered name',`<input class="inp" id="co-name" value="${esc(C.name)}">`)}${field('Tagline',`<input class="inp" id="co-tag" value="${esc(C.tagline)}">`)}${field('Company registration no.',`<input class="inp" id="co-reg" value="${esc(C.reg)}" placeholder="e.g. 2023/123456/07">`)}${field('VAT number',`<input class="inp" id="co-vat" value="${esc(C.vatNo)}">`)}${field('Address',`<input class="inp" id="co-addr" value="${esc(C.address)}">`,'span2')}${field('Accounts email',`<input class="inp" id="co-email" value="${esc(C.email)}">`)}${field('Phone',`<input class="inp" id="co-phone" value="${esc(C.phone)}">`)}${field('Website',`<input class="inp" id="co-web" value="${esc(C.website||'www.bemosolutions.co.za')}">`)}${field('Banking details for invoices',`<input class="inp" id="co-bank" value="${esc(C.bank)}" placeholder="Bank · account no. · branch code">`,'span2')}${field('POPIA Information Officer',`<input class="inp" id="co-io" value="${esc(C.infoOfficer)}">`)}</div><div class="row mt-16" style="justify-content:flex-end"><button class="btn pri" data-a="saveCompany">${ic('check',14)}Save company details</button></div>`);
  if(sec==='users') body = card('Team members', table({key:'users', rows:DB.users, act:u=>`data-a="editUser" data-id="${u.id}"`, cols:[{k:'name',l:'Name',r:u=>who(u.id)+(u.id===DB.me?' <span class="tag">You</span>':'')},{k:'email',l:'Email',r:u=>`<span class="mono small">${esc(u.email)}</span>`},{k:'role',l:'Job title'},{k:'dept',l:'Department'},{k:'sysRole',l:'System role',r:u=>badge(u.sysRole,u.sysRole==='Owner'?'cyan':'gray','nodot')},{k:'capacity',l:'Hours / week',cls:'r',r:u=>`<span class="num">${u.alloc}h / ${u.capacity}h</span>`},{k:'status',l:'Availability',r:u=>badge(u.status)}]}), {flush:true, act:`<button class="btn sm pri" data-a="inviteUser">${ic('user-plus',13)}Add team member</button>`});
  if(sec==='roles') body = card('Roles & permissions', `<div class="tw"><table class="tbl"><thead><tr><th>Permission</th>${ROLES.map(r=>`<th class="perm">${r}</th>`).join('')}</tr></thead><tbody>${PERMS.map(([k,l])=>`<tr><td>${l}</td>${ROLES.map(r=>`<td class="perm"><input type="checkbox" style="accent-color:var(--accent);width:15px;height:15px" ${S.perms[r].includes(k)?'checked':''} ${r==='Owner'?'disabled':''} data-ch="perm" data-r="${r}" data-k="${k}" aria-label="${l} for ${r}"></td>`).join('')}</tr>`).join('')}</tbody></table></div><p class="muted xs" style="padding:10px 16px">This matrix defines the access policy. It is enforced once accounts move to Supabase Auth with row-level security. Owner permissions are locked.</p>`, {flush:true});
  if(sec==='teams') body = `<div class="grid g3">${DEPTS().map(dp=>{ const us=DB.users.filter(u=>u.dept===dp); const lead=us.find(u=>/Head|Lead|Founder|CEO|Director|Manager/.test(u.role))||us[0]; return card(dp, us.length?`<div class="row between small"><span class="muted">Lead</span>${who(lead.id)}</div><div class="row between small mt-12"><span class="muted">Members</span>${avs(us.map(u=>u.id),8)}</div><div class="row between small mt-12"><span class="muted">Weekly capacity</span><b>${sum(us,u=>u.capacity)}h</b></div>`:'<p class="muted small">No members yet.</p>'); }).join('')}</div>`;
  if(sec==='templates') body = `<div class="col gap-16">${card('Project types', `<p class="sub small" style="margin-bottom:10px">Your own list of project types. New types are also added automatically when you type one on a project or quote.</p><div class="row wrap">${(S.projectTypes||[]).map((t,i)=>`<span class="tag">${esc(t)}<button class="ib sm" style="width:16px;height:16px" data-a="typeDel" data-i="${i}" aria-label="Remove ${esc(t)}">${ic('x',11)}</button></span>`).join('')||'<span class="muted small">No project types yet.</span>'}<span class="row" style="gap:4px"><input class="inp sm" id="ptype-new" placeholder="Add a project type" style="width:180px" data-enter="typeAdd"><button class="btn xs" data-a="typeAdd">${ic('plus',12)}</button></span></div>`)}${card('Project templates', DB.templates.length?`<div class="col gap-12">${DB.templates.map(t=>`<div style="border:1px solid var(--line);border-radius:10px;padding:12px"><div class="row between"><b>${esc(t.name)}</b><div class="row">${t.category?catTag(t.category):''}<button class="ib sm" data-a="tplRemove" data-id="${t.id}" data-tip="Delete template" aria-label="Delete template">${ic('trash-2',14)}</button></div></div><div class="row wrap mt-8">${t.ws.map((w,i)=>`<span class="tag"><span class="mono muted">${i+1}</span>${esc(w)}<button class="ib sm" style="width:16px;height:16px" data-a="tplDel" data-id="${t.id}" data-i="${i}" aria-label="Remove ${esc(w)}">${ic('x',11)}</button></span>`).join('')}<span class="row" style="gap:4px"><input class="inp sm" id="tpl-${t.id}" placeholder="Add stage" style="width:150px" data-enter="tplAdd" data-id="${t.id}"><button class="btn xs" data-a="tplAdd" data-id="${t.id}">${ic('plus',12)}</button></span></div></div>`).join('')}</div>`:empty('layout-template','No templates','Templates are optional. Create one for work you repeat often, or tick “Save these stages as a template” when you create a project.'), {act:`<button class="btn sm pri" data-a="tplNew">${ic('plus',13)}New template</button>`})}</div>`;
  if(sec==='workflow') body = card('Workflow settings', [setRow('Classify new enquiries automatically','Runs the intake rules as soon as an enquiry is logged', SW('w1',S.workflow.autoClassify,'wfSet','data-k="autoClassify"')), setRow('New leads go to','<b>Sales pool</b>: every Sales rep is notified and the first to claim it owns it. <b>Auto-assign</b>: the Sales rep with the fewest open tasks gets it.', `<select class="sel sm" data-ch="wfSel" data-k="enquiryRouting">${opts([['pool','Sales pool (claim)'],['auto','Auto-assign']], S.workflow.enquiryRouting||'pool')}</select>`), setRow('Escalate unclaimed leads after (hours)','Team leaders are notified when a pool task is still unclaimed', `<input class="inp sm num" type="number" style="width:80px" value="${S.workflow.poolEscalateHours??4}" data-ch="wfNum" data-k="poolEscalateHours">`), setRow('Quote follow-up every (days)','After a quote is sent, the sender is reminded to follow up until the client accepts or rejects', `<input class="inp sm num" type="number" style="width:80px" value="${S.workflow.quoteFollowDays??3}" data-ch="wfNum" data-k="quoteFollowDays">`), setRow('Invoice reminder before due date (days)','First reminder to chase payment', `<input class="inp sm num" type="number" style="width:80px" value="${S.workflow.invoiceRemindBefore??3}" data-ch="wfNum" data-k="invoiceRemindBefore">`), setRow('Repeat invoice reminders every (days)','Keeps reminding until the invoice is paid or cancelled', `<input class="inp sm num" type="number" style="width:80px" value="${S.workflow.invoiceRepeatDays??7}" data-ch="wfNum" data-k="invoiceRepeatDays">`), setRow('Tell the team leader after (days overdue)','When a reminder or task is this late, the person’s team leader is notified', `<input class="inp sm num" type="number" style="width:80px" value="${S.workflow.escalateDays??1}" data-ch="wfNum" data-k="escalateDays">`), setRow('Email reminders to staff','Once a day, each person gets an email of what is due, and team leaders get their team summary. Needs the website/n8n connection and someone to have the CRM open that day.', SW('w9',S.workflow.emailReminders!==false,'wfSet','data-k="emailReminders"')), setRow('Internal review before sending quotes','Quotes must pass internal review before they can be sent', SW('w3',S.workflow.quoteApproval,'wfSet','data-k="quoteApproval"')), setRow('Deposit required before project start','New projects start as Awaiting authorization', SW('w4',S.workflow.depositRequired,'wfSet','data-k="depositRequired"')), setRow('Deposit percentage','Applied when creating a deposit invoice from a quote', `<input class="inp sm num" type="number" style="width:80px" value="${S.workflow.depositPct}" data-ch="wfNum" data-k="depositPct">`), setRow('Enquiry response target (hours)','Enquiries older than this without contact are highlighted', `<input class="inp sm num" type="number" style="width:80px" value="${S.workflow.followUpHours}" data-ch="wfNum" data-k="followUpHours">`), setRow('VAT rate (%)','South African standard rate, applied to new quotes and invoices', `<input class="inp sm num" type="number" style="width:80px" value="${S.workflow.vat}" data-ch="wfNum" data-k="vat">`)].join(''));
  if(sec==='notif') body = card('Notification preferences', `<div class="eyebrow">Channels</div>${[['inapp','In-app','Bell and notification centre'],['email','Email','Needs the email integration'],['whatsapp','WhatsApp','Needs WhatsApp Business'],['digest','Daily digest','Needs the email integration']].map(([k,t,s])=>setRow(t,s,SW('n-'+k,S.notif[k],'notifSet',`data-k="${k}"`))).join('')}<div class="eyebrow mt-16">Events</div>${[['enquiries','New enquiries assigned to me'],['overdue','Overdue invoices and tasks'],['payments','Payments received'],['mentions','Comments and mentions']].map(([k,t])=>setRow(t,'',SW('n-'+k,S.notif[k],'notifSet',`data-k="${k}"`))).join('')}`);
  if(sec==='integ') body = card('Integrations', `<p class="sub" style="margin-bottom:12px">Track connection status on the Integrations page.</p><div class="list" style="border:1px solid var(--line);border-radius:10px">${DB.integrations.map(i=>`<div class="li"><span class="int-ic" style="width:30px;height:30px">${ic(i.icon,15)}</span><div class="grow"><div class="t">${esc(i.name)}</div><div class="s">${esc(i.desc)}</div></div>${badge(i.status, i.status==='Connected'?'green':'gray')}</div>`).join('')}</div><a class="btn sm mt-12" href="#integrations">Open Integrations ${ic('arrow-right',13)}</a>`);
  if(sec==='security') body = card('Security', [setRow('Require multi-factor authentication','All users must enrol an authenticator app', SW('s1',S.security.mfa,'secSet','data-k="mfa"')), setRow('Single sign-on (Microsoft Entra ID)','', SW('s2',S.security.sso,'secSet','data-k="sso"')), setRow('Session timeout','Users are signed out after inactivity', `<select class="sel sm" data-ch="secSel" data-k="session">${opts(['1 hour','8 hours','12 hours','24 hours'],S.security.session)}</select>`), setRow('Restrict sign-in to office IP ranges','', SW('s3',S.security.ipAllow,'secSet','data-k="ipAllow"')), setRow('Human approval for AI actions','AI can suggest but never approve quotes, confirm scope or deploy. Cannot be disabled.', SW('s4',true,'secSet','data-k="aiApproval"',true))].join('')+AUTH_NOTE+`<div class="callout mt-12">${ic('shield',15)}<span>POPIA Information Officer: ${C.infoOfficer?esc(C.infoOfficer):'<b>not set</b> — add one under Company details'}.</span></div>`);
  if(sec==='audit') body = card('Audit log', table({key:'audit', rows:DB.audit, emptyMsg:empty('scroll-text','No events yet','Every change made in this workspace is recorded here.'), cols:[{k:'at',l:'Time',r:a=>fmtDT(a.at)},{k:'user',l:'User',r:a=>who(a.user),sv:a=>a.user},{k:'action',l:'Action',r:a=>`<span class="cell-t">${esc(a.action)}</span>`},{k:'target',l:'Target',r:a=>`<span class="mono small">${esc(a.target)}</span>`},{k:'ip',l:'Source',r:a=>`<span class="small muted">${esc(a.ip)}</span>`}]}), {flush:true});
  if(sec==='data'){ let size=0; try{ size = JSON.stringify(DB).length; }catch(e){} const last = pref.get('lastBackup', null);
    body = `${last && days(last,TODAY)<7 ? '' : `<div class="callout amber" style="margin-bottom:14px">${ic('alert-triangle',15)}<span>${last?`Last backup was on ${fmtD(last)}.`:'You have not exported a backup yet.'} Your records live only in this browser — clearing browser data or changing computer loses them. Export a backup at least weekly.</span></div>`}`+card('Backup & data', [setRow('Storage used', `${(size/1024).toFixed(0)} KB of records in this browser · documents are kept separately in browser file storage`, `<span class="tag">${ic('hard-drive',12)}This browser</span>`), setRow('Export backup','Download every record as a JSON file. Uploaded document files are not included — keep the originals.', `<button class="btn sm pri" data-a="exportData">${ic('download',13)}Export backup</button>`), setRow('Restore from backup','Replace everything in this browser with a backup file', `<label class="btn sm" for="imp-file">${ic('upload',13)}Restore…</label><input type="file" id="imp-file" accept=".json,application/json" style="display:none" data-ch="importData">`), setRow('Erase all data','Delete every record in this browser and start again from setup', `<button class="btn sm danger" data-a="resetData">${ic('trash-2',13)}Erase</button>`)].join('')+`<div class="mt-16">${window.bulkDeleteCard?bulkDeleteCard():''}</div>`+`<div class="callout mt-16">${ic('database',15)}<span>Next step for a shared, multi-user system: move these records to Supabase (Postgres with row-level security). The data model here maps one-to-one to those tables.</span></div>`); }
  if(sec==='appearance'){ const th = document.documentElement.getAttribute('data-theme')||'system'; body = card('Appearance', setRow('Theme','System follows your device setting', `<div class="seg">${[['system','System','monitor'],['light','Light','sun'],['dark','Dark','moon']].map(([v,l,i])=>`<button class="${th===v?'on':''}" data-a="setTheme" data-v="${v}">${ic(i,14)}${l}</button>`).join('')}</div>`) + setRow('Density','Compact shows more rows in tables and boards', `<div class="seg">${[['comfortable','Comfortable'],['compact','Compact']].map(([v,l])=>`<button class="${(pref.get('density','comfortable'))===v?'on':''}" data-a="setDensity" data-v="${v}">${l}</button>`).join('')}</div>`) + setRow('Collapse sidebar','Show icons only', `<button class="btn sm" data-a="toggleSb">${ic('panel-left',13)}Toggle</button>`)); }
  const html = `<div class="page full">${pageHead('Administration', 'Company details, team, permissions, templates, workflow rules, security and backups.')}
    <div class="split" style="grid-template-columns:230px minmax(0,1fr)"><div class="card"><div class="card-b subnav" style="padding:8px">${nav.map(([v,l,i])=>`<button class="${sec===v?'on':''}" data-a="seg" data-key="adm" data-v="${v}">${ic(i,15)}${l}</button>`).join('')}</div></div><div class="tabpane">${body}</div></div></div>`;
  return {html, crumbs:[['Administration','admin'],[(nav.find(n=>n[0]===sec)||nav[0])[1]]], title:'Administration'};
};
A.saveCompany = () => { const C = DB.settings.company; Object.assign(C,{name:val('co-name')||C.name, tagline:val('co-tag'), reg:val('co-reg'), vatNo:val('co-vat'), address:val('co-addr'), email:val('co-email'), phone:val('co-phone'), website:val('co-web'), bank:val('co-bank'), infoOfficer:val('co-io')}); audit('Updated company details',''); commit('Company details saved'); };
A.perm = (v,d) => { const S=DB.settings; const arr=S.perms[d.r]; if(v){ if(!arr.includes(d.k)) arr.push(d.k); } else S.perms[d.r]=arr.filter(x=>x!==d.k); audit('Changed permission', `${d.r}: ${d.k} ${v?'granted':'revoked'}`); save(); toast(`${d.r} permission ${v?'granted':'revoked'}`); };
A.wfSet = (v,d) => { DB.settings.workflow[d.k]=v; audit('Changed workflow setting', d.k+' → '+(v?'on':'off')); save(); toast('Workflow setting saved'); };
A.wfNum = (v,d) => { DB.settings.workflow[d.k]=Math.max(0,+v||0); audit('Changed workflow setting', d.k+' → '+v); save(); toast('Saved'); };
A.notifSet = (v,d) => { DB.settings.notif[d.k]=v; save(); toast('Notification preference saved'); };
A.secSet = (v,d) => { DB.settings.security[d.k]=v; audit('Changed security setting', `${d.k} → ${v?'on':'off'}`); save(); toast('Security setting saved'); };
A.secSel = (v,d) => { DB.settings.security[d.k]=v; save(); toast('Saved'); };
A.typeAdd = () => { const v = val('ptype-new'); if(!v) return; const S=DB.settings; S.projectTypes = S.projectTypes||[]; if(!S.projectTypes.includes(v)) S.projectTypes.push(v); commit('Project type added'); setTimeout(()=>{ const i=document.getElementById('ptype-new'); i&&i.focus(); },0); };
A.typeDel = d => { DB.settings.projectTypes.splice(+d.i,1); commit('Project type removed'); };
A.tplNew = () => modal({title:'New project template', body:`<div class="form-grid">${field('Template name *',`<input class="inp" id="tn-name" placeholder="e.g. Standard website build">`,'span2')}${field('Project type',`<input class="inp" id="tn-type" list="ptype-list2"><datalist id="ptype-list2">${STATUS.categories.map(x=>`<option value="${esc(x)}">`).join('')}</datalist>`)}${field('Typical length (weeks)',`<input class="inp num" type="number" id="tn-weeks" value="4">`)}${field('Stages (one per line) *',`<textarea class="ta" id="tn-ws" style="min-height:140px"></textarea>`,'span2')}</div>`, foot:`<button class="btn ghost" data-a="closeTop">Cancel</button><button class="btn pri" data-a="tplSave">Save template</button>`});
A.tplSave = () => { if(!requireFields([['tn-name','Template name'],['tn-ws','Stages']])) return; const ws = val('tn-ws').split('\n').map(x=>x.trim()).filter(Boolean); const cat = val('tn-type'); if(cat && !(DB.settings.projectTypes||[]).includes(cat)) (DB.settings.projectTypes=DB.settings.projectTypes||[]).push(cat); DB.templates.push({id:'TPL-'+Date.now().toString(36), name:val('tn-name'), category:cat, ws, weeks:+val('tn-weeks')||4}); closeTop(); commit('Template saved'); };
A.tplRemove = d => confirmBox({title:'Delete template?', text:'Projects already created from it are not affected.', ok:'Delete', danger:true, onOk:()=>{ DB.templates = DB.templates.filter(t=>t.id!==d.id); commit('Template deleted'); }});
A.wfSel = (v,d) => { DB.settings.workflow[d.k]=v; audit('Changed workflow setting', d.k+' → '+v); save(); toast('Saved'); };
A.tplDel = d => { const t=DB.templates.find(x=>x.id===d.id); t.ws.splice(+d.i,1); commit('Workstream removed from template'); };
A.tplAdd = d => { const v=val('tpl-'+d.id); if(!v) return; DB.templates.find(x=>x.id===d.id).ws.push(v); commit('Workstream added'); };
function userForm(u){ return `<div class="form-grid">${field('Full name *',`<input class="inp" id="iu-name" value="${esc(u.name||'')}">`)}${field('Work email *',`<input class="inp" id="iu-email" type="email" value="${esc(u.email||'')}">`)}${field('Job title',`<input class="inp" id="iu-role" value="${esc(u.role||'')}">`)}${field('Department',`<input class="inp" id="iu-dept" list="dept-list" value="${esc(u.dept||'Engineering')}"><datalist id="dept-list">${DEPTS().map(x=>`<option value="${esc(x)}">`).join('')}</datalist>`)}${field('Phone',`<input class="inp" id="iu-phone" value="${esc(u.phone&&u.phone!=='—'?u.phone:'')}">`)}${field('System role',`<select class="sel" id="iu-sys" ${u.id===DB.me&&u.sysRole==='Owner'?'disabled':''}>${opts(u.sysRole==='Owner'?ROLES:ROLES.slice(1), u.sysRole||'Sales')}</select>`)}${field('Capacity (hours / week)',`<input class="inp num" type="number" id="iu-cap" value="${u.capacity||40}">`)}${field('Allocated (hours / week)',`<input class="inp num" type="number" id="iu-alloc" value="${u.alloc||0}">`)}${field('Availability',`<select class="sel" id="iu-st">${opts(['Available','Busy','On leave'], u.status||'Available')}</select>`)}${field('Reports to (team leader)',`<select class="sel" id="iu-lead">${opts(DB.users.filter(x=>x.id!==u.id && ['Owner','Admin','Team leader'].includes(x.sysRole)).map(x=>[x.id,x.name+' · '+x.sysRole]), u.leader||'', {blank:'Nobody'})}</select>`)}</div><p class="muted xs mt-12"><b>Team leader</b> sees their team’s work and gets notified about their reminders. <b>Sales</b> claims leads and sends quotes. <b>Delivery</b> works on projects. <b>Finance</b> sends invoices and chases payment.</p>`; }
A.inviteUser = () => { closePop(); modal({title:'Add team member', body:userForm({})+`<p class="muted xs mt-12">They appear in assignments, workload and reports straight away. Individual sign-in comes with Supabase Auth.</p>`, foot:`<button class="btn ghost" data-a="closeTop">Cancel</button><button class="btn pri" data-a="saveUser">${ic('user-plus',14)}Add member</button>`}); };
A.editUser = d => { const u=get.user(d.id); modal({title:'Edit '+esc(u.name), body:userForm(u), foot:`${u.id!==DB.me?`<button class="btn danger" data-a="removeUser" data-id="${u.id}" style="margin-right:auto">${ic('user-minus',14)}Remove</button>`:''}<button class="btn ghost" data-a="closeTop">Cancel</button><button class="btn pri" data-a="saveUser" data-id="${u.id}">Save</button>`}); };
A.saveUser = d => { if(!requireFields([['iu-name','Full name'],['iu-email','Work email']])) return; let u = d.id ? get.user(d.id) : {id:'U'+String(Math.max(0,...DB.users.map(x=>+x.id.slice(1)||0))+1).padStart(2,'0'), joined:TODAY};
  Object.assign(u,{name:val('iu-name'), email:val('iu-email'), role:val('iu-role')||'Team member', dept:val('iu-dept')||'General', phone:val('iu-phone')||'—', sysRole:document.getElementById('iu-sys').disabled?u.sysRole:val('iu-sys'), capacity:Math.max(1,+val('iu-cap')||40), alloc:Math.max(0,+val('iu-alloc')||0), status:val('iu-st'), leader:val('iu-lead')||null});
  if(!d.id) DB.users.push(u); audit(d.id?'Updated team member':'Added team member', u.name); closeTop(); commit(d.id?'Saved':`${u.name} added`); };
A.removeUser = d => { const u=get.user(d.id); const open = DB.tasks.filter(t=>t.assignee===u.id && t.status!=='Done').length; closeTop(); confirmBox({title:'Remove '+esc(u.name)+'?', text: open?`${esc(u.name)} still owns ${open} open task${open>1?'s':''}. Their tasks, clients and projects will be reassigned to you.`:'They will be removed from the team list. Their past activity stays in the history.', ok:'Remove', danger:true, onOk:()=>{ DB.tasks.forEach(t=>{ if(t.assignee===u.id && t.status!=='Done') t.assignee=DB.me; if(t.reviewer===u.id) t.reviewer=DB.me; }); (DB.reminders||[]).forEach(r=>{ if(r.owner===u.id) r.owner=DB.me; }); DB.users.forEach(x=>{ if(x.leader===u.id) x.leader=null; }); DB.clients.forEach(c=>{ if(c.owner===u.id) c.owner=DB.me; if(c.assistant===u.id) c.assistant=DB.me; }); DB.projects.forEach(p=>{ ['owner','pm','tech'].forEach(k=>{ if(p[k]===u.id) p[k]=DB.me; }); p.team=p.team.filter(x=>x!==u.id); p.workstreams.forEach(w=>{ if(w.owner===u.id) w.owner=DB.me; if(w.reviewer===u.id) w.reviewer=DB.me; }); }); u.removed=true; DB.users = DB.users.filter(x=>x.id!==u.id); DB.formerUsers=(DB.formerUsers||[]).concat([u]); audit('Removed team member', u.name); commit(`${u.name} removed`); }}); };
A.exportData = () => { const blob = new Blob([JSON.stringify(DB,null,2)], {type:'application/json'}); const u = URL.createObjectURL(blob); const a = document.createElement('a'); a.href=u; a.download=`bemo-solutions-backup-${TODAY}.json`; document.body.append(a); a.click(); a.remove(); setTimeout(()=>URL.revokeObjectURL(u), 30000); pref.set('lastBackup', TODAY); audit('Exported backup',''); save(); setTimeout(rerender, 200); toast('Backup downloaded — store it somewhere safe'); };
A.importData = (v, d, el) => { const f = el.files && el.files[0]; if(!f) return; const r = new FileReader(); r.onload = () => { let data; try { data = JSON.parse(String(r.result)); } catch(e){ return toast('That file is not a valid backup','err'); } if(!data || !Array.isArray(data.clients) || !Array.isArray(data.users)) return toast('That file is not an BEMO-SOLUTIONS backup','err');
  confirmBox({title:'Restore this backup?', text:`The backup contains ${data.clients.length} clients, ${(data.projects||[]).length} projects and ${(data.invoices||[]).length} invoices. <b>Everything currently in this browser will be replaced.</b>`, ok:'Replace and restore', danger:true, onOk:()=>{ replaceDB(data); if(!get.user(DB.me)) DB.me = (DB.users[0]||{}).id; DB.setupDone = !!DB.users.length; saveNow(); go('home'); renderShellCounts(); toast('Backup restored'); }}); }; r.readAsText(f); el.value=''; };
A.resetData = () => confirmBox({title:'Erase all data?', text:'Every client, enquiry, quote, invoice, project, task and setting in this browser is permanently deleted. Export a backup first if you might need it.', ok:'Erase everything', danger:true, onOk:()=>{ (DB.documents||[]).forEach(x=>(x.versions||[]).forEach(v=>v.blobKey&&FILES.del(v.blobKey))); resetDB(); pref.set('hideSetup', false); location.hash=''; render(true); }});

/* ===================== FIRST-RUN SETUP ===================== */
Views.setup = () => `<div style="min-height:100%;display:grid;place-items:center;padding:32px max(16px,env(safe-area-inset-left,0px))">
  <div style="width:min(560px,100%)" class="col gap-16">
    <div class="row" style="gap:12px"><span class="logo" style="width:40px;height:40px;border-radius:11px">${LOGO(24)}</span><div><div class="strong" style="font-size:18px">BEMO-SOLUTIONS Operations OS</div><div class="muted small">Set up your workspace</div></div></div>
    <div class="card"><div class="card-b col gap-16" style="padding:22px">
      <p class="sub" style="line-height:1.6">The workspace starts empty. Add your company and yourself as the owner — you can add your team, clients and everything else afterwards.</p>
      <div class="form-grid">${field('Company name *',`<input class="inp" id="su-co" value="BEMO-SOLUTIONS (Pty) Ltd">`,'span2')}${field('Your full name *',`<input class="inp" id="su-name" autofocus>`)}${field('Your job title',`<input class="inp" id="su-role" value="Founder & CEO">`)}${field('Work email *',`<input class="inp" id="su-email" type="email">`)}${field('Phone',`<input class="inp" id="su-phone">`)}</div>
      <button class="btn pri" data-a="finishSetup" style="height:38px">${ic('arrow-right',15)}Create workspace</button>
      <div class="callout">${ic('hard-drive',15)}<span>Records are saved in this browser on this computer. Export backups regularly from Administration. Moving to a shared online database (Supabase) is the next step for multi-user access.</span></div>
      <div class="row between" style="border-top:1px solid var(--line);padding-top:14px"><span class="muted small">Moving from another computer?</span><label class="btn sm" for="imp-file">${ic('upload',13)}Restore a backup</label><input type="file" id="imp-file" accept=".json,application/json" style="display:none" data-ch="importData"></div>
    </div></div></div></div>`;
A.finishSetup = () => { if(!requireFields([['su-co','Company name'],['su-name','Your name'],['su-email','Work email']])) return;
  const u = {id:'U01', name:val('su-name'), role:val('su-role')||'Owner', dept:'Leadership', sysRole:'Owner', status:'Available', capacity:40, alloc:0, email:val('su-email'), phone:val('su-phone')||'—', joined:TODAY};
  DB.users = [u]; DB.me = u.id; DB.settings.company.name = val('su-co'); DB.settings.company.email = val('su-email'); DB.setupDone = true; audit('Created workspace', DB.settings.company.name); saveNow(); location.hash=''; render(true); toast('Workspace ready'); };
A.setDensity = d => { pref.set('density', d.v); document.documentElement.setAttribute('data-density', d.v); rerender(); };
try { document.documentElement.setAttribute('data-density', pref.get('density','comfortable')); } catch(e){}

})();
